var textForPages =["\u041d\u043e\u0432\u043e\u0441\u0442\u043d\u043e\u0439 \u0434\u0430\u0439\u0434\u0436\u0435\u0441\u0442 20\u201327 \u043c\u0430\u0440\u0442\u0430 2026 \u0433\u043e\u0434\u0430\u000d\u000a\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u000d\u000a\u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439\u000d\u000a\u0413\u043b\u0430\u0432\u043d\u043e\u0435 \u0432 \u0432\u044b\u043f\u0443\u0441\u043a\u0435\u000d\u000a\u042d\u043a\u0441\u043f\u043e\u0440\u0442 \u043d\u0435\u0444\u0442\u0438 \u0441 \u0411\u043b\u0438\u0436\u043d\u0435\u0433\u043e \u0412\u043e\u0441\u0442\u043e\u043a\u0430 \u000d\u000a\u0440\u0443\u0445\u043d\u0443\u043b \u043d\u0430 60%\u000d\u000a\u0411\u043b\u043e\u043a\u0430\u0434\u0430 \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u043e\u0433\u043e \u043f\u0440\u043e\u043b\u0438\u0432\u0430 \u043e\u0431\u0440\u0443\u0448\u0438\u043b\u0430 \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0438 \u000d\u000a\u043d\u0435\u0444\u0442\u0438 \u0438\u0437 \u0432\u043e\u0441\u044c\u043c\u0438 \u0441\u0442\u0440\u0430\u043d \u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u0433\u043e \u0437\u0430\u043b\u0438\u0432\u0430. \u0411\u043e\u043b\u0435\u0435 \u000d\u000a50 \u043c\u043b\u043d \u0431\u0430\u0440\u0440\u0435\u043b\u0435\u0439 \u0441\u043a\u043e\u043f\u0438\u043b\u043e\u0441\u044c \u0432 \u043f\u043b\u0430\u0432\u0443\u0447\u0438\u0445 \u000d\u000a\u0445\u0440\u0430\u043d\u0438\u043b\u0438\u0449\u0430\u0445. \u0420\u0435\u0433\u0438\u043e\u043d \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0438\u0432\u0430\u043b 36% \u043c\u0438\u0440\u043e\u0432\u043e\u0433\u043e \u000d\u000a\u043c\u043e\u0440\u0441\u043a\u043e\u0433\u043e \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u0430 \u043d\u0435\u0444\u0442\u0438.\u000d\u000a\u0418\u0440\u0430\u043d\u0441\u043a\u0438\u0435 \u0443\u0434\u0430\u0440\u044b \u0432\u044b\u0432\u0435\u043b\u0438 \u0438\u0437 \u0441\u0442\u0440\u043e\u044f \u000d\u000a17% \u043a\u0430\u0442\u0430\u0440\u0441\u043a\u0438\u0445 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0435\u0439 \u043f\u043e \u0421\u041f\u0413\u000d\u000a\u041f\u043e\u0432\u0440\u0435\u0436\u0434\u0435\u043d\u044b 2 \u0438\u0437 14 \u043b\u0438\u043d\u0438\u0439 \u0441\u0436\u0438\u0436\u0435\u043d\u0438\u044f \u0433\u0430\u0437\u0430. \u000d\u000a\u041f\u043e\u0442\u0435\u0440\u0438 \u2014 12,8 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u0421\u041f\u0413 \u0432 \u0433\u043e\u0434 (~$20 \u043c\u043b\u0440\u0434). \u000d\u000a\u0412\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u0435 \u0437\u0430\u0439\u043c\u0435\u0442 \u0442\u0440\u0438\u2013\u043f\u044f\u0442\u044c \u043b\u0435\u0442. \u041a\u0430\u0442\u0430\u0440 \u000d\u000a\u043e\u0431\u044a\u044f\u0432\u0438\u043b \u0444\u043e\u0440\u0441-\u043c\u0430\u0436\u043e\u0440 \u043f\u043e \u043a\u043e\u043d\u0442\u0440\u0430\u043a\u0442\u0430\u043c \u0441 \u0415\u0432\u0440\u043e\u043f\u043e\u0439 \u000d\u000a\u0438 \u0410\u0437\u0438\u0435\u0439.\u000d\u000a\u0414\u0440\u043e\u043d\u044b \u043d\u0430\u0440\u0443\u0448\u0438\u043b\u0438 \u0440\u0430\u0431\u043e\u0442\u0443 \u043e\u0431\u043b\u0430\u0447\u043d\u044b\u0445 \u000d\u000a\u0441\u0435\u0440\u0432\u0438\u0441\u043e\u0432 Amazon \u0432 \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0435\u000d\u000a\u0412\u0442\u043e\u0440\u043e\u0439 \u0441\u0431\u043e\u0439 AWS \u0437\u0430 \u043c\u0435\u0441\u044f\u0446 \u0438\u0437-\u0437\u0430 \u0432\u043e\u0435\u043d\u043d\u044b\u0445 \u000d\u000a\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0439. Amazon \u043f\u0435\u0440\u0435\u0431\u0440\u0430\u0441\u044b\u0432\u0430\u0435\u0442 \u043d\u0430\u0433\u0440\u0443\u0437\u043a\u0443 \u000d\u000a\u0432 \u0434\u0440\u0443\u0433\u0438\u0435 \u0440\u0435\u0433\u0438\u043e\u043d\u044b. \u042d\u0442\u043e \u043f\u0435\u0440\u0432\u044b\u0435 \u0441\u043b\u0443\u0447\u0430\u0438, \u043a\u043e\u0433\u0434\u0430 \u000d\u000a\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442 \u043d\u0430\u043f\u0440\u044f\u043c\u0443\u044e \u0431\u044c\u0435\u0442 \u043f\u043e \u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0435 \u000d\u000aBigTech.\u000d\u000a\u0411\u0430\u0445\u0440\u0435\u0439\u043d \u043f\u0440\u043e\u0434\u0432\u0438\u0433\u0430\u0435\u0442 \u0440\u0435\u0437\u043e\u043b\u044e\u0446\u0438\u044e \u041e\u041e\u041d \u000d\u000a\u0441 \u043f\u0440\u0430\u0432\u043e\u043c \u043f\u0440\u0438\u043c\u0435\u043d\u0435\u043d\u0438\u044f \u0441\u0438\u043b\u044b \u0432 \u041e\u0440\u043c\u0443\u0437\u0435\u000d\u000a\u041f\u0440\u043e\u0435\u043a\u0442 \u0434\u043e\u043f\u0443\u0441\u043a\u0430\u0435\u0442 \u0432\u043e\u0435\u043d\u043d\u044b\u0435 \u043e\u043f\u0435\u0440\u0430\u0446\u0438\u0438 \u0434\u043b\u044f \u0437\u0430\u0449\u0438\u0442\u044b \u000d\u000a\u0441\u0443\u0434\u043e\u0445\u043e\u0434\u0441\u0442\u0432\u0430. \u0424\u0440\u0430\u043d\u0446\u0438\u044f \u0432\u044b\u0434\u0432\u0438\u043d\u0443\u043b\u0430 \u0430\u043b\u044c\u0442\u0435\u0440\u043d\u0430\u0442\u0438\u0432\u043d\u044b\u0439 \u000d\u000a\u043c\u044f\u0433\u043a\u0438\u0439 \u0432\u0430\u0440\u0438\u0430\u043d\u0442 \u0431\u0435\u0437 \u0443\u043f\u043e\u043c\u0438\u043d\u0430\u043d\u0438\u044f \u0418\u0440\u0430\u043d\u0430 \u0438 \u0431\u0435\u0437 \u000d\u000a\u0441\u0438\u043b\u043e\u0432\u043e\u0433\u043e \u043a\u043e\u043c\u043f\u043e\u043d\u0435\u043d\u0442\u0430.\u000d\u000aZijin Gold \u043d\u0430\u0440\u0430\u0449\u0438\u0432\u0430\u0435\u0442 \u0434\u043e\u043b\u044e \u0432 Chifeng \u000d\u000aJilong \u0434\u043e 26% \u0437\u0430 $2,64 \u043c\u043b\u0440\u0434\u000d\u000a\u041a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u0435 \u0437\u043e\u043b\u043e\u0442\u043e\u0434\u043e\u0431\u044b\u0442\u0447\u0438\u043a\u0438 \u0430\u0433\u0440\u0435\u0441\u0441\u0438\u0432\u043d\u043e \u0441\u043a\u0443\u043f\u0430\u044e\u0442 \u000d\u000a\u0430\u043a\u0442\u0438\u0432\u044b, \u043f\u043e\u043a\u0430 \u0437\u0430\u043f\u0430\u0434\u043d\u044b\u0435 \u043a\u043e\u043d\u043a\u0443\u0440\u0435\u043d\u0442\u044b \u0441\u043e\u043a\u0440\u0430\u0449\u0430\u044e\u0442 \u000d\u000a\u0434\u043e\u0431\u044b\u0447\u0443. Zijin \u0432 2025 \u0433\u043e\u0434\u0443 \u0443\u0442\u0440\u043e\u0438\u043b\u0430 \u043f\u0440\u0438\u0431\u044b\u043b\u044c \u000d\u000a\u0434\u043e $1,87 \u043c\u043b\u0440\u0434 \u0438 \u043f\u043b\u0430\u043d\u0438\u0440\u0443\u0435\u0442 \u043d\u0430\u0440\u0430\u0441\u0442\u0438\u0442\u044c \u0434\u043e\u0431\u044b\u0447\u0443 \u000d\u000a\u043d\u0430 26%.\u000d\u000a\u0418\u0440\u0430\u043d \u0440\u0430\u0437\u0440\u0435\u0448\u0438\u043b \u043f\u0440\u043e\u0445\u043e\u0434 \u00ab\u043d\u0435\u0432\u0440\u0430\u0436\u0434\u0435\u0431\u043d\u044b\u043c\u00bb \u000d\u000a\u0441\u0443\u0434\u0430\u043c \u0447\u0435\u0440\u0435\u0437 \u041e\u0440\u043c\u0443\u0437\u000d\u000a\u0421\u0443\u0434\u0430 \u0438\u0437 \u041a\u0438\u0442\u0430\u044f, \u0420\u043e\u0441\u0441\u0438\u0438, \u0418\u043d\u0434\u0438\u0438, \u0418\u0440\u0430\u043a\u0430 \u0438 \u041f\u0430\u043a\u0438\u0441\u0442\u0430\u043d\u0430 \u000d\u000a\u043f\u043e\u043b\u0443\u0447\u0438\u043b\u0438 \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043d\u0438\u0435 \u043d\u0430 \u043f\u0440\u043e\u0445\u043e\u0434. \u0418\u0440\u0430\u043d \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u0442 \u000d\u000a\u043a\u0430\u0436\u0434\u044b\u0439 \u0442\u0430\u043d\u043a\u0435\u0440 \u043f\u0435\u0440\u0435\u0434 \u043e\u0442\u043a\u0440\u044b\u0442\u0438\u0435\u043c \u043f\u0440\u043e\u0445\u043e\u0434\u0430 \u2014 \u000d\u000a\u0444\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u0432\u0432\u043e\u0434\u0438\u0442 \u0440\u0443\u0447\u043d\u043e\u0439 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u043d\u0430\u0434 \u043c\u0438\u0440\u043e\u0432\u043e\u0439 \u000d\u000a\u043d\u0435\u0444\u0442\u044f\u043d\u043e\u0439 \u0430\u0440\u0442\u0435\u0440\u0438\u0435\u0439.\u000d\u000aAlba \u0441\u043e\u043a\u0440\u0430\u0449\u0430\u0435\u0442 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f \u000d\u000a\u043d\u0430 19%\u000d\u000a\u041a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0439 \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u0435\u0432\u044b\u0439 \u0437\u0430\u0432\u043e\u0434 \u0432 \u043c\u0438\u0440\u0435 \u0438\u043c\u0435\u0435\u0442 \u000d\u000a\u0437\u0430\u043f\u0430\u0441 \u0441\u044b\u0440\u044c\u044f \u043d\u0430 \u043c\u0435\u0441\u044f\u0446. \u041f\u0435\u0440\u0435\u0437\u0430\u043f\u0443\u0441\u043a \u043b\u0438\u043d\u0438\u0439 \u0437\u0430\u0439\u043c\u0435\u0442 \u000d\u000a\u0442\u0440\u0438-\u0447\u0435\u0442\u044b\u0440\u0435 \u043c\u0435\u0441\u044f\u0446\u0430. \u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u0438\u0449\u0435\u0442 \u000d\u000a\u0430\u043b\u044c\u0442\u0435\u0440\u043d\u0430\u0442\u0438\u0432\u043d\u044b\u0435 \u043c\u0430\u0440\u0448\u0440\u0443\u0442\u044b \u0447\u0435\u0440\u0435\u0437 \u041e\u043c\u0430\u043d \u0438 \u0415\u0433\u0438\u043f\u0435\u0442.\u000d\u000a\u0421\u0428\u0410 \u043e\u0434\u043e\u0431\u0440\u0438\u043b\u0438 \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0438 \u0432\u043e\u043e\u0440\u0443\u0436\u0435\u043d\u0438\u044f \u000d\u000a\u041e\u0410\u042d \u043d\u0430 $7 \u043c\u043b\u0440\u0434\u000d\u000aPatriot PAC-3 \u043d\u0430 $5,6 \u043c\u043b\u0440\u0434 \u0438 \u0432\u0435\u0440\u0442\u043e\u043b\u0435\u0442\u044b Chinook \u000d\u000a\u043d\u0430 $1,32 \u043c\u043b\u0440\u0434. \u0421\u0434\u0435\u043b\u043a\u0438 \u043e\u0444\u043e\u0440\u043c\u043b\u0435\u043d\u044b \u043a\u0430\u043a \u0440\u0430\u0441\u0448\u0438\u0440\u0435\u043d\u0438\u0435 \u000d\u000a\u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044e\u0449\u0438\u0445 \u043a\u043e\u043d\u0442\u0440\u0430\u043a\u0442\u043e\u0432 \u2014 \u0431\u0435\u0437 \u043f\u0443\u0431\u043b\u0438\u0447\u043d\u043e\u0433\u043e \u000d\u000a\u0440\u0430\u0441\u043a\u0440\u044b\u0442\u0438\u044f.\u000d\u000a\u041a\u0438\u0442\u0430\u0439 \u0432\u043b\u043e\u0436\u0438\u043b $120 \u043c\u043b\u0440\u0434 \u0432 \u0434\u043e\u0431\u044b\u0447\u0443 \u000d\u000a\u043a\u0440\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u043c\u0438\u043d\u0435\u0440\u0430\u043b\u043e\u0432 \u0437\u0430 \u0440\u0443\u0431\u0435\u0436\u043e\u043c \u000d\u000a\u0441 2023 \u0433\u043e\u0434\u0430\u000d\u000a\u041a\u043e\u043d\u0442\u0440\u043e\u043b\u0438\u0440\u0443\u0435\u0442 90% \u043c\u0438\u0440\u043e\u0432\u043e\u0433\u043e \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u000d\u000a\u0440\u0435\u0434\u043a\u043e\u0437\u0435\u043c\u043e\u0432, 60% \u043f\u0435\u0440\u0435\u0440\u0430\u0431\u043e\u0442\u043a\u0438 \u043b\u0438\u0442\u0438\u044f, \u2028\u000d\u000a70% \u2014 \u043a\u043e\u0431\u0430\u043b\u044c\u0442\u0430. \u0421\u0442\u0440\u0430\u0442\u0435\u0433\u0438\u044f \u044d\u0432\u043e\u043b\u044e\u0446\u0438\u043e\u043d\u0438\u0440\u043e\u0432\u0430\u043b\u0430: \u000d\u000a\u0442\u0435\u043f\u0435\u0440\u044c \u041f\u0435\u043a\u0438\u043d \u0441\u0442\u0440\u043e\u0438\u0442 \u0432 \u0441\u0442\u0440\u0430\u043d\u0430\u0445-\u043f\u0430\u0440\u0442\u043d\u0435\u0440\u0430\u0445 \u043f\u043e\u043b\u043d\u0443\u044e \u000d\u000a\u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0443 \u0432 \u043e\u0431\u043c\u0435\u043d \u043d\u0430 \u0434\u043e\u043b\u0433\u043e\u0441\u0440\u043e\u0447\u043d\u044b\u0435 \u000d\u000a\u043a\u043e\u043d\u0442\u0440\u0430\u043a\u0442\u044b.\u000d\u000aDP World: \u043f\u043e\u0440\u0442 \u0414\u0436\u0435\u0431\u0435\u043b\u044c-\u0410\u043b\u0438 \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442, \u000d\u000a\u043d\u0435\u0441\u043c\u043e\u0442\u0440\u044f \u043d\u0430 \u0430\u0442\u0430\u043a\u0438\u000d\u000a\u0412\u044b\u0440\u0443\u0447\u043a\u0430 \u043e\u043f\u0435\u0440\u0430\u0442\u043e\u0440\u0430 \u0432\u044b\u0440\u043e\u0441\u043b\u0430 \u043d\u0430 22%, \u2028\u000d\u000a\u0434\u043e $24,4 \u043c\u043b\u0440\u0434, \u043f\u0440\u0438\u0431\u044b\u043b\u044c \u2014 \u043d\u0430 32%. \u041d\u043e \u0432\u0445\u043e\u0434\u044f\u0449\u0438\u0439 \u000d\u000a\u043f\u043e\u0442\u043e\u043a \u0441\u0443\u0434\u043e\u0432 \u0443\u0436\u0435 \u0441\u043d\u0438\u0436\u0430\u0435\u0442\u0441\u044f. \u0412 2026 \u0433\u043e\u0434\u0443 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u000d\u000a\u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0440\u0443\u0435\u0442 $3 \u043c\u043b\u0440\u0434 \u0432 \u0440\u0430\u0437\u0432\u0438\u0442\u0438\u0435 \u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u044b.\u000d\u000a01 11","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 20\u201327 \u043c\u0430\u0440\u0442\u0430 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b #\u043b\u043e\u0433\u0438\u0441\u0442\u0438\u043a\u0430 #\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b\u000d\u000aAlba \u0438\u0449\u0435\u0442 \u0430\u043b\u044c\u0442\u0435\u0440\u043d\u0430\u0442\u0438\u0432\u043d\u044b\u0435 \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0438 \u0441\u044b\u0440\u044c\u044f \u2028\u000d\u000a\u043d\u0430 \u0444\u043e\u043d\u0435 \u0437\u0430\u043a\u0440\u044b\u0442\u0438\u044f \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u043e\u0433\u043e \u043f\u0440\u043e\u043b\u0438\u0432\u0430\u000d\u000a\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0438\u0432\u0430\u0435\u0442 \u043e\u043a\u043e\u043b\u043e 9% \u043c\u0438\u0440\u043e\u0432\u043e\u0433\u043e \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f \u2014 \u043a\u043b\u044e\u0447\u0435\u0432\u043e\u0433\u043e \u000d\u000a\u043c\u0435\u0442\u0430\u043b\u043b\u0430 \u0434\u043b\u044f \u0441\u0442\u0440\u043e\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0430, \u0442\u0440\u0430\u043d\u0441\u043f\u043e\u0440\u0442\u0430 \u0438 \u0432\u043e\u0437\u043e\u0431\u043d\u043e\u0432\u043b\u044f\u0435\u043c\u043e\u0439 \u044d\u043d\u0435\u0440\u0433\u0435\u0442\u0438\u043a\u0438. \u041d\u0430 \u041b\u043e\u043d\u0434\u043e\u043d\u0441\u043a\u043e\u0439 \u0431\u0438\u0440\u0436\u0435 \u000d\u000a\u043c\u0435\u0442\u0430\u043b\u043b\u043e\u0432 \u0441\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u044c \u0442\u0440\u0435\u0445\u043c\u0435\u0441\u044f\u0447\u043d\u044b\u0445 \u0444\u044c\u044e\u0447\u0435\u0440\u0441\u043e\u0432 \u043d\u0430 \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u0439 \u2014 $3,4 \u0442\u044b\u0441. \u0437\u0430 \u0442\u043e\u043d\u043d\u0443.\u000d\u000a\u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0441\u043a\u0430\u044f \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f Aluminium Bahrain (Alba), \u000d\u000a\u0443\u043f\u0440\u0430\u0432\u043b\u044f\u044e\u0449\u0430\u044f \u043e\u0434\u043d\u0438\u043c \u0438\u0437 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0445 \u000d\u000a\u0430\u043b\u044e\u043c\u0438\u043d\u0438\u0435\u0432\u044b\u0445 \u0437\u0430\u0432\u043e\u0434\u043e\u0432 \u0432 \u043c\u0438\u0440\u0435, \u0440\u0430\u0441\u043f\u043e\u043b\u0430\u0433\u0430\u0435\u0442 \u000d\u000a\u0437\u0430\u043f\u0430\u0441\u0430\u043c\u0438 \u0441\u044b\u0440\u044c\u044f \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u043d\u0430 \u043e\u0434\u0438\u043d \u043c\u0435\u0441\u044f\u0446 \u000d\u000a\u0440\u0430\u0431\u043e\u0442\u044b \u043f\u0440\u0438 \u0442\u0435\u043a\u0443\u0449\u0438\u0445 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0445 \u000d\u000a\u043f\u043e\u043a\u0430\u0437\u0430\u0442\u0435\u043b\u044f\u0445. \u041e\u0431 \u044d\u0442\u043e\u043c \u0441\u043e\u043e\u0431\u0449\u0438\u043b \u0433\u0435\u043d\u0434\u0438\u0440\u0435\u043a\u0442\u043e\u0440 \u000d\u000a\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u0410\u043b\u0438 \u0430\u043b\u044c-\u0411\u0430\u043a\u0430\u043b\u0438. \u000a\u000d\u000a\u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u043e\u0431\u044a\u044f\u0432\u0438\u043b\u0430 \u0444\u043e\u0440\u0441-\u043c\u0430\u0436\u043e\u0440 4 \u043c\u0430\u0440\u0442\u0430, \u000d\u000a\u043f\u043e\u0441\u043a\u043e\u043b\u044c\u043a\u0443 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u044f \u043d\u0430 \u0441\u0443\u0434\u043e\u0445\u043e\u0434\u0441\u0442\u0432\u043e \u0447\u0435\u0440\u0435\u0437 \u000d\u000a\u041e\u0440\u043c\u0443\u0437\u0441\u043a\u0438\u0439 \u043f\u0440\u043e\u043b\u0438\u0432 \u0441\u043e\u0440\u0432\u0430\u043b\u0438 \u043a\u0430\u043a \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0438 \u000d\u000a\u043f\u0440\u043e\u0434\u0443\u043a\u0446\u0438\u0438 \u043a\u043b\u0438\u0435\u043d\u0442\u0430\u043c, \u0442\u0430\u043a \u0438 \u0438\u043c\u043f\u043e\u0440\u0442 \u0433\u043b\u0438\u043d\u043e\u0437\u0435\u043c\u0430 \u2014 \u000d\u000a\u043a\u043b\u044e\u0447\u0435\u0432\u043e\u0433\u043e \u0441\u044b\u0440\u044c\u044f \u0434\u043b\u044f \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f. \u000d\u000a\u041f\u043e \u0441\u043b\u043e\u0432\u0430\u043c \u0433\u043b\u0430\u0432\u044b \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438, Alba \u0430\u043a\u0442\u0438\u0432\u043d\u043e \u0438\u0449\u0435\u0442 \u000d\u000a\u0430\u043b\u044c\u0442\u0435\u0440\u043d\u0430\u0442\u0438\u0432\u043d\u044b\u0435 \u043c\u0430\u0440\u0448\u0440\u0443\u0442\u044b \u043f\u043e\u0441\u0442\u0430\u0432\u043e\u043a, \u0447\u0442\u043e\u0431\u044b \u000d\u000a\u0443\u0432\u0435\u043b\u0438\u0447\u0438\u0442\u044c \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u044b\u0439 \u0437\u0430\u043f\u0430\u0441 \u0441\u044b\u0440\u044c\u044f.\u000a\u000d\u000aAlba \u0443\u0436\u0435 \u043d\u0430\u0447\u0430\u043b\u0430 \u043f\u0435\u0440\u0435\u043d\u0430\u043f\u0440\u0430\u0432\u043b\u044f\u0442\u044c \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u043d\u044b\u0435 \u000d\u000a\u043f\u043e\u0442\u043e\u043a\u0438 \u043f\u043e \u0441\u0443\u0448\u0435 \u0438 \u043c\u043e\u0440\u044e \u0432 \u043e\u0431\u0445\u043e\u0434 \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u043e\u0433\u043e \u000d\u000a\u043f\u0440\u043e\u043b\u0438\u0432\u0430, \u0430 \u0442\u0430\u043a\u0436\u0435 \u043e\u0440\u0433\u0430\u043d\u0438\u0437\u043e\u0432\u0430\u043b\u0430 \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0438 \u0447\u0435\u0440\u0435\u0437 \u000d\u000a\u0415\u0433\u0438\u043f\u0435\u0442 \u0441 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u0438\u0435\u043c \u0430\u0432\u0438\u0430\u043f\u0435\u0440\u0435\u0432\u043e\u0437\u043e\u043a. \u000d\u000a\u0412 \u0447\u0438\u0441\u043b\u0435 \u0440\u0430\u0441\u0441\u043c\u0430\u0442\u0440\u0438\u0432\u0430\u0435\u043c\u044b\u0445 \u0430\u043b\u044c\u0442\u0435\u0440\u043d\u0430\u0442\u0438\u0432\u043d\u044b\u0445 \u000d\u000a\u043b\u043e\u0433\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u0443\u0437\u043b\u043e\u0432 \u2014 \u043e\u043c\u0430\u043d\u0441\u043a\u0438\u0439 \u043f\u043e\u0440\u0442 \u0421\u043e\u0445\u0430\u0440. \u000d\u000a\u0414\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u0443\u044e \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0443 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u000d\u000a\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442 \u0441\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0430\u044f \u0433\u043e\u0440\u043d\u043e\u0434\u043e\u0431\u044b\u0432\u0430\u044e\u0449\u0430\u044f \u000d\u000a\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f Maaden, \u043a\u043e\u0442\u043e\u0440\u0430\u044f \u0443\u0436\u0435 \u0434\u043e\u0441\u0442\u0430\u0432\u0438\u043b\u0430 \u043e\u0434\u043d\u0443 \u000d\u000a\u043f\u0430\u0440\u0442\u0438\u044e \u0433\u043b\u0438\u043d\u043e\u0437\u0435\u043c\u0430.\u000a\u000d\u000a\u041d\u0430 \u0444\u043e\u043d\u0435 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u0439 \u043f\u043e\u0441\u0442\u0430\u0432\u043e\u043a Alba \u000d\u000a\u0432\u044b\u043d\u0443\u0436\u0434\u0435\u043d\u0430 \u0431\u044b\u043b\u0430 \u0441\u043e\u043a\u0440\u0430\u0442\u0438\u0442\u044c \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u000d\u000a\u043d\u0430 19% \u043e\u0442 \u043e\u0431\u0449\u0435\u0439 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0438 \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u044f \u000d\u000a\u0432 1,6 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u0432 \u0433\u043e\u0434. \u041f\u043e \u043e\u0446\u0435\u043d\u043a\u0435 \u0440\u0443\u043a\u043e\u0432\u043e\u0434\u0441\u0442\u0432\u0430, \u000d\u000a\u043f\u0435\u0440\u0435\u0437\u0430\u043f\u0443\u0441\u043a \u043b\u0438\u043d\u0438\u0439 \u0437\u0430\u0439\u043c\u0435\u0442 \u043d\u0435 \u043c\u0435\u043d\u0435\u0435 \u0442\u0440\u0435\u0445\u0447\u0435\u0442\u044b\u0440\u0435\u0445 \u043c\u0435\u0441\u044f\u0446\u0435\u0432. \u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u043d\u0435 \u0438\u0441\u043a\u043b\u044e\u0447\u0430\u0435\u0442 \u000d\u000a\u0434\u0430\u043b\u044c\u043d\u0435\u0439\u0448\u0435\u0433\u043e \u0441\u043e\u043a\u0440\u0430\u0449\u0435\u043d\u0438\u044f \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u000d\u000a\u0432 \u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u0438 \u043e\u0442 \u0441\u0438\u0442\u0443\u0430\u0446\u0438\u0438 \u0441 \u0441\u044b\u0440\u044c\u0435\u043c.\u000d\u000a#\u043b\u043e\u0433\u0438\u0441\u0442\u0438\u043a\u0430 #\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b\u000d\u000a\u0418\u0440\u0430\u043d \u0440\u0430\u0437\u0440\u0435\u0448\u0438\u043b \u00ab\u043d\u0435\u0432\u0440\u0430\u0436\u0434\u0435\u0431\u043d\u044b\u043c\u00bb \u0441\u0443\u0434\u0430\u043c \u043f\u0440\u043e\u0445\u043e\u0434\u0438\u0442\u044c \u000d\u000a\u0447\u0435\u0440\u0435\u0437 \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u0438\u0439 \u043f\u0440\u043e\u043b\u0438\u0432\u000d\u000a\u0412 \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0438\u0435 \u0434\u043d\u0438 \u0418\u0440\u0430\u043d \u0440\u0430\u0437\u0440\u0435\u0448\u0430\u0435\u0442 \u043d\u0435\u0431\u043e\u043b\u044c\u0448\u043e\u043c\u0443 \u0447\u0438\u0441\u043b\u0443 \u0442\u0430\u043d\u043a\u0435\u0440\u043e\u0432 \u043f\u0435\u0440\u0435\u0441\u0435\u043a\u0430\u0442\u044c \u0441\u0432\u043e\u0438 \u000d\u000a\u0442\u0435\u0440\u0440\u0438\u0442\u043e\u0440\u0438\u0430\u043b\u044c\u043d\u044b\u0435 \u0432\u043e\u0434\u044b, \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u044f \u0438\u0445, \u043f\u0440\u0435\u0436\u0434\u0435 \u0447\u0435\u043c \u043e\u0442\u043a\u0440\u044b\u0442\u044c \u043f\u0440\u043e\u0445\u043e\u0434 \u0447\u0435\u0440\u0435\u0437 \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u0438\u0439 \u043f\u0440\u043e\u043b\u0438\u0432.\u000d\u000a\u0418\u0440\u0430\u043d \u043d\u0430\u043f\u0440\u0430\u0432\u0438\u043b \u0441\u0442\u0440\u0430\u043d\u0430\u043c \u2014 \u0447\u043b\u0435\u043d\u0430\u043c \u000d\u000a\u041c\u0435\u0436\u0434\u0443\u043d\u0430\u0440\u043e\u0434\u043d\u043e\u0439 \u043c\u043e\u0440\u0441\u043a\u043e\u0439 \u043e\u0440\u0433\u0430\u043d\u0438\u0437\u0430\u0446\u0438\u0438 \u043f\u0438\u0441\u044c\u043c\u043e, \u000d\u000a\u0432 \u043a\u043e\u0442\u043e\u0440\u043e\u043c \u0433\u043e\u0432\u043e\u0440\u0438\u0442\u0441\u044f, \u0447\u0442\u043e \u00ab\u043d\u0435\u0432\u0440\u0430\u0436\u0434\u0435\u0431\u043d\u044b\u0435 \u000d\u000a\u0441\u0443\u0434\u0430\u00bb \u043c\u043e\u0433\u0443\u0442 \u043f\u0440\u043e\u0445\u043e\u0434\u0438\u0442\u044c \u0447\u0435\u0440\u0435\u0437 \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u0438\u0439 \u000d\u000a\u043f\u0440\u043e\u043b\u0438\u0432 \u0432 \u043a\u043e\u043e\u0440\u0434\u0438\u043d\u0430\u0446\u0438\u0438 \u0441 \u0432\u043b\u0430\u0441\u0442\u044f\u043c\u0438 \u0438\u0441\u043b\u0430\u043c\u0441\u043a\u043e\u0439 \u000d\u000a\u0440\u0435\u0441\u043f\u0443\u0431\u043b\u0438\u043a\u0438, \u0441\u043e\u043e\u0431\u0449\u0430\u0435\u0442 Financial Times.\u000d\u000a\u041c\u0438\u043d\u0438\u0441\u0442\u0440 \u0438\u043d\u043e\u0441\u0442\u0440\u0430\u043d\u043d\u044b\u0445 \u0434\u0435\u043b \u0418\u0440\u0430\u043d\u0430 \u0410\u0431\u0431\u0430\u0441 \u0410\u0440\u0430\u0433\u0447\u0438 \u000d\u000a\u0443\u0442\u043e\u0447\u043d\u0438\u043b, \u0447\u0442\u043e \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043d\u0438\u0435 \u043d\u0430 \u043f\u0440\u043e\u0445\u043e\u0434 \u0447\u0435\u0440\u0435\u0437 \u000d\u000a\u041e\u0440\u043c\u0443\u0437\u0441\u043a\u0438\u0439 \u043f\u0440\u043e\u043b\u0438\u0432 \u043f\u043e\u043b\u0443\u0447\u0438\u043b\u0438 \u0441\u0443\u0434\u0430 \u0438\u0437 \u041a\u0438\u0442\u0430\u044f, \u000d\u000a\u0420\u043e\u0441\u0441\u0438\u0438, \u0418\u043d\u0434\u0438\u0438, \u0418\u0440\u0430\u043a\u0430 \u0438 \u041f\u0430\u043a\u0438\u0441\u0442\u0430\u043d\u0430. \u0418\u0440\u0430\u043d\u0441\u043a\u0438\u0435 \u000d\u000a\u0447\u0438\u043d\u043e\u0432\u043d\u0438\u043a\u0438 \u0438 \u0440\u0430\u043d\u0435\u0435 \u043f\u043e\u0434\u0447\u0435\u0440\u043a\u0438\u0432\u0430\u043b\u0438, \u0447\u0442\u043e \u043c\u043e\u0440\u0441\u043a\u043e\u0439 \u000d\u000a\u043f\u0443\u0442\u044c \u0437\u0430\u043a\u0440\u044b\u0442 \u0442\u043e\u043b\u044c\u043a\u043e \u0434\u043b\u044f \u00ab\u0432\u0440\u0430\u0436\u0435\u0441\u043a\u0438\u0445 \u0441\u0443\u0434\u043e\u0432\u00bb.\u000d\u000a02 11","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 20\u201327 \u043c\u0430\u0440\u0442\u0430 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0430 #\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u0410\u043a\u0446\u0438\u043e\u043d\u0435\u0440\u044b Alba \u043e\u0434\u043e\u0431\u0440\u0438\u043b\u0438 \u0434\u0438\u0432\u0438\u0434\u0435\u043d\u0434\u044b \u0438 \u043f\u043e\u043a\u0443\u043f\u043a\u0443 \u000d\u000a\u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0435\u0433\u043e \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u0435\u0432\u043e\u0433\u043e \u0437\u0430\u0432\u043e\u0434\u0430 \u0432 \u0415\u0421\u000d\u000a\u041f\u043e \u0438\u0442\u043e\u0433\u0430\u043c 2025 \u0433\u043e\u0434\u0430 \u0447\u0438\u0441\u0442\u0430\u044f \u043f\u0440\u0438\u0431\u044b\u043b\u044c Alba \u0443\u0432\u0435\u043b\u0438\u0447\u0438\u043b\u0430\u0441\u044c \u0434\u043e 218,7 \u043c\u043b\u043d \u0434\u0438\u043d\u0430\u0440\u043e\u0432 ($582 \u043c\u043b\u043d) \u000d\u000a\u043f\u0440\u043e\u0442\u0438\u0432 184,5 \u043c\u043b\u043d \u0434\u0438\u043d\u0430\u0440\u043e\u0432 \u0433\u043e\u0434\u043e\u043c \u0440\u0430\u043d\u0435\u0435. \u041e\u0431\u0449\u0438\u0439 \u0434\u043e\u0445\u043e\u0434 \u0432\u044b\u0440\u043e\u0441 \u043d\u0430 16% \u0432 \u0433\u043e\u0434\u043e\u0432\u043e\u043c \u0432\u044b\u0440\u0430\u0436\u0435\u043d\u0438\u0438 \u000d\u000a\u0438 \u0434\u043e\u0441\u0442\u0438\u0433 213,2 \u043c\u043b\u043d \u0434\u0438\u043d\u0430\u0440\u043e\u0432.\u000d\u000a\u0410\u043a\u0446\u0438\u043e\u043d\u0435\u0440\u044b Aluminium Bahrain (Alba) \u0443\u0442\u0432\u0435\u0440\u0434\u0438\u043b\u0438 \u000d\u000a\u0432\u044b\u043f\u043b\u0430\u0442\u0443 \u0444\u0438\u043d\u0430\u043b\u044c\u043d\u044b\u0445 \u0434\u0438\u0432\u0438\u0434\u0435\u043d\u0434\u043e\u0432 \u0437\u0430 2025 \u0433\u043e\u0434 \u000d\u000a\u0432 \u0440\u0430\u0437\u043c\u0435\u0440\u0435 44% \u043e\u0442 \u0443\u0441\u0442\u0430\u0432\u043d\u043e\u0433\u043e \u043a\u0430\u043f\u0438\u0442\u0430\u043b\u0430, \u0438\u043b\u0438 \u000d\u000a62 \u043c\u043b\u043d \u0431\u0430\u0445\u0440\u0435\u0439\u043d\u0441\u043a\u0438\u0445 \u0434\u0438\u043d\u0430\u0440\u043e\u0432 ($164 \u043c\u043b\u043d). \u000d\u000a\u041e\u0431 \u044d\u0442\u043e\u043c \u0433\u043e\u0432\u043e\u0440\u0438\u0442\u0441\u044f \u0432 \u0437\u0430\u044f\u0432\u043b\u0435\u043d\u0438\u0438 \u0431\u0430\u0445\u0440\u0435\u0439\u043d\u0441\u043a\u043e\u0439 \u000d\u000a\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438. \u000a\u000d\u000a\u0421 \u0443\u0447\u0435\u0442\u043e\u043c \u0440\u0430\u043d\u0435\u0435 \u043e\u0431\u044a\u044f\u0432\u043b\u0435\u043d\u043d\u044b\u0445 \u0432\u044b\u043f\u043b\u0430\u0442 \u000d\u000a\u0441\u043e\u0432\u043e\u043a\u0443\u043f\u043d\u044b\u0435 \u0434\u0438\u0432\u0438\u0434\u0435\u043d\u0434\u044b \u0437\u0430 \u043f\u0440\u043e\u0448\u043b\u044b\u0439 \u000d\u000a\u0433\u043e\u0434 \u0441\u043e\u0441\u0442\u0430\u0432\u044f\u0442 76,5 \u043c\u043b\u043d \u0434\u0438\u043d\u0430\u0440\u043e\u0432 ($203 \u043c\u043b\u043d). \u000d\u000a\u0424\u0438\u043d\u0430\u043b\u044c\u043d\u044b\u0435 \u0434\u0438\u0432\u0438\u0434\u0435\u043d\u0434\u044b \u0431\u0443\u0434\u0443\u0442 \u0432\u044b\u043f\u043b\u0430\u0447\u0435\u043d\u044b \u000d\u000a\u0430\u043a\u0446\u0438\u043e\u043d\u0435\u0440\u0430\u043c 8 \u0430\u043f\u0440\u0435\u043b\u044f.\u000a\u000d\u000a\u041d\u0430 \u0441\u043e\u0431\u0440\u0430\u043d\u0438\u0438 \u0442\u0430\u043a\u0436\u0435 \u0431\u044b\u043b\u043e \u043e\u0434\u043e\u0431\u0440\u0435\u043d\u043e \u000d\u000a\u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u043e \u043f\u0440\u0438\u043e\u0431\u0440\u0435\u0442\u0435\u043d\u0438\u0438 100% \u0430\u043a\u0446\u0438\u0439 \u000d\u000a\u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u044f Aluminium Dunkerque \u2014 \u000d\u000a\u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0435\u0433\u043e \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044f \u043f\u0435\u0440\u0432\u0438\u0447\u043d\u043e\u0433\u043e \u000d\u000a\u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f \u0432 \u0415\u0432\u0440\u043e\u043f\u0435\u0439\u0441\u043a\u043e\u043c \u0441\u043e\u044e\u0437\u0435.\u000d\u000a#\u043b\u043e\u0433\u0438\u0441\u0442\u0438\u043a\u0430 #\u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0430 #\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b\u000d\u000aDP World \u0437\u0430\u044f\u0432\u0438\u043b\u0430, \u0447\u0442\u043e \u043f\u043e\u0440\u0442 \u0414\u0436\u0435\u0431\u0435\u043b\u044c-\u0410\u043b\u0438 \u000d\u000a\u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0430\u0435\u0442 \u0444\u0443\u043d\u043a\u0446\u0438\u043e\u043d\u0438\u0440\u043e\u0432\u0430\u0442\u044c\u000d\u000a\u0414\u0436\u0435\u0431\u0435\u043b\u044c \u0410\u043b\u0438 \u2014 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0439 \u043c\u043e\u0440\u0441\u043a\u043e\u0439 \u043f\u043e\u0440\u0442 \u043d\u0430 \u0411\u043b\u0438\u0436\u043d\u0435\u043c \u0412\u043e\u0441\u0442\u043e\u043a\u0435 \u0438 \u043e\u0434\u0438\u043d \u0438\u0437 \u043a\u043b\u044e\u0447\u0435\u0432\u044b\u0445 \u000d\u000a\u0433\u043b\u043e\u0431\u0430\u043b\u044c\u043d\u044b\u0445 \u043b\u043e\u0433\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u0445\u0430\u0431\u043e\u0432, \u0441\u0432\u044f\u0437\u044b\u0432\u0430\u044e\u0449\u0438\u0439 \u0442\u043e\u0440\u0433\u043e\u0432\u044b\u0435 \u043f\u043e\u0442\u043e\u043a\u0438 \u043c\u0435\u0436\u0434\u0443 \u0410\u0437\u0438\u0435\u0439, \u0415\u0432\u0440\u043e\u043f\u043e\u0439 \u000d\u000a\u0438 \u0410\u0444\u0440\u0438\u043a\u043e\u0439. \u0412 \u043d\u0430\u0447\u0430\u043b\u0435 \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u0430 \u0418\u0440\u0430\u043d \u043d\u0435\u043e\u0434\u043d\u043e\u043a\u0440\u0430\u0442\u043d\u043e \u0430\u0442\u0430\u043a\u043e\u0432\u0430\u043b \u043f\u043e\u0440\u0442 \u0440\u0430\u043a\u0435\u0442\u0430\u043c\u0438 \u000d\u000a\u0438 \u0431\u0435\u0441\u043f\u0438\u043b\u043e\u0442\u043d\u0438\u043a\u0430\u043c\u0438, \u0431\u043e\u043b\u044c\u0448\u0438\u043d\u0441\u0442\u0432\u043e \u0438\u0437 \u043a\u043e\u0442\u043e\u0440\u044b\u0445 \u0431\u044b\u043b\u0438 \u043f\u0435\u0440\u0435\u0445\u0432\u0430\u0447\u0435\u043d\u044b.\u000d\u000a\u042d\u043c\u0438\u0440\u0430\u0442\u0441\u043a\u0438\u0439 \u043b\u043e\u0433\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u043e\u043f\u0435\u0440\u0430\u0442\u043e\u0440 DP World \u000d\u000a\u0437\u0430\u044f\u0432\u0438\u043b, \u0447\u0442\u043e \u0440\u0430\u0441\u043f\u043e\u043b\u043e\u0436\u0435\u043d\u043d\u044b\u0439 \u0432 \u0414\u0443\u0431\u0430\u0435 \u000d\u000a\u0433\u043b\u0443\u0431\u043e\u043a\u043e\u0432\u043e\u0434\u043d\u044b\u0439 \u043f\u043e\u0440\u0442 \u0414\u0436\u0435\u0431\u0435\u043b\u044c \u0410\u043b\u0438 \u000d\u000a\u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0430\u0435\u0442 \u0444\u0443\u043d\u043a\u0446\u0438\u043e\u043d\u0438\u0440\u043e\u0432\u0430\u0442\u044c, \u043d\u0435\u0441\u043c\u043e\u0442\u0440\u044f \u000d\u000a\u043d\u0430 \u0438\u0440\u0430\u043d\u0441\u043a\u0438\u0435 \u0430\u0442\u0430\u043a\u0438 \u0438 \u0444\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u0443\u044e \u0431\u043b\u043e\u043a\u0430\u0434\u0443 \u000d\u000a\u041e\u0440\u043c\u0443\u0437\u0441\u043a\u043e\u0433\u043e \u043f\u0440\u043e\u043b\u0438\u0432\u0430. \u041e\u0431 \u044d\u0442\u043e\u043c \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u000d\u000a\u0441\u043e\u043e\u0431\u0449\u0438\u043b\u0430 \u043e\u0434\u043d\u043e\u0432\u0440\u0435\u043c\u0435\u043d\u043d\u043e \u0441 \u043f\u0443\u0431\u043b\u0438\u043a\u0430\u0446\u0438\u0435\u0439 \u000d\u000a\u0444\u0438\u043d\u0430\u043d\u0441\u043e\u0432\u044b\u0445 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u043e\u0432 \u0437\u0430 2025 \u0433\u043e\u0434.\u000a\u000d\u000a\u041f\u043e \u0438\u0442\u043e\u0433\u0430\u043c \u043f\u0440\u043e\u0448\u043b\u043e\u0433\u043e \u0433\u043e\u0434\u0430 \u043f\u043e\u0440\u0442 \u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043b \u000d\u000a\u0441\u043e\u0432\u043e\u043a\u0443\u043f\u043d\u044b\u0439 \u0440\u043e\u0441\u0442 \u043e\u0431\u044a\u0435\u043c\u0430 \u043e\u043f\u0435\u0440\u0430\u0446\u0438\u0439 \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u000d\u000a\u043d\u0430 9%. \u041f\u0440\u0438 \u044d\u0442\u043e\u043c \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u043f\u0440\u0438\u0437\u043d\u0430\u043b\u0430, \u0447\u0442\u043e \u000d\u000a\u0432 \u043d\u0430\u0441\u0442\u043e\u044f\u0449\u0435\u0435 \u0432\u0440\u0435\u043c\u044f \u0432\u0445\u043e\u0434\u044f\u0449\u0438\u0439 \u043f\u043e\u0442\u043e\u043a \u0441\u0443\u0434\u043e\u0432 \u000d\u000a\u0441\u043d\u0438\u0437\u0438\u043b\u0441\u044f \u0438\u0437 \u0437\u0430 \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0430\u044e\u0449\u0435\u0439\u0441\u044f \u0432\u043e\u0435\u043d\u043d\u043e\u0439 \u000d\u000a\u043e\u043f\u0435\u0440\u0430\u0446\u0438\u0438 \u0421\u0428\u0410 \u0438 \u0418\u0437\u0440\u0430\u0438\u043b\u044f \u043f\u0440\u043e\u0442\u0438\u0432 \u0418\u0440\u0430\u043d\u0430.\u000d\u000a\u0421\u043e\u0433\u043b\u0430\u0441\u043d\u043e \u0444\u0438\u043d\u0430\u043d\u0441\u043e\u0432\u043e\u043c\u0443 \u043e\u0442\u0447\u0435\u0442\u0443 DP World, \u0432\u044b\u0440\u0443\u0447\u043a\u0430 \u000d\u000a\u043b\u043e\u0433\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u043e\u043f\u0435\u0440\u0430\u0442\u043e\u0440\u0430 \u0432\u044b\u0440\u043e\u0441\u043b\u0430 \u043d\u0430 22% \u000d\u000a\u0432 \u0433\u043e\u0434\u043e\u0432\u043e\u043c \u0432\u044b\u0440\u0430\u0436\u0435\u043d\u0438\u0438 \u0438 \u0434\u043e\u0441\u0442\u0438\u0433\u043b\u0430 $24,4 \u043c\u043b\u0440\u0434. \u000d\u000a\u0427\u0438\u0441\u0442\u0430\u044f \u043f\u0440\u0438\u0431\u044b\u043b\u044c \u0443\u0432\u0435\u043b\u0438\u0447\u0438\u043b\u0430\u0441\u044c \u043d\u0430 32% \u2014 \u043f\u043e\u0447\u0442\u0438 \u000d\u000a\u0434\u043e $2 \u043c\u043b\u0440\u0434. \u041e\u043f\u0435\u0440\u0430\u0446\u0438\u043e\u043d\u043d\u044b\u0439 \u0434\u0435\u043d\u0435\u0436\u043d\u044b\u0439 \u043f\u043e\u0442\u043e\u043a \u000d\u000a\u0432\u044b\u0440\u043e\u0441 \u043d\u0430 14% \u0438 \u0441\u043e\u0441\u0442\u0430\u0432\u0438\u043b $6,3 \u043c\u043b\u0440\u0434.\u000a\u000d\u000a\u0412 \u043f\u0440\u043e\u0448\u043b\u043e\u043c \u0433\u043e\u0434\u0443 \u043a\u0430\u043f\u0438\u0442\u0430\u043b\u044c\u043d\u044b\u0435 \u0437\u0430\u0442\u0440\u0430\u0442\u044b DP World \u000d\u000a\u0434\u043e\u0441\u0442\u0438\u0433\u043b\u0438 $3,1 \u043c\u043b\u0440\u0434 \u043f\u043e \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044e \u0441 $2,2 \u043c\u043b\u0440\u0434 \u000d\u000a\u0433\u043e\u0434\u043e\u043c \u0440\u0430\u043d\u0435\u0435. \u042d\u0442\u043e \u043f\u043e\u0437\u0432\u043e\u043b\u0438\u043b\u043e \u0443\u0432\u0435\u043b\u0438\u0447\u0438\u0442\u044c \u2028\u000d\u000a\u0441\u043e\u0432\u043e\u043a\u0443\u043f\u043d\u0443\u044e \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u044c \u043f\u043e\u0440\u0442\u043e\u0432 \u0434\u043e 109 \u043c\u043b\u043d TEU. \u000d\u000a\u041d\u0430 2026 \u0433\u043e\u0434 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u0437\u0430\u043f\u043b\u0430\u043d\u0438\u0440\u043e\u0432\u0430\u043b\u0430 \u000d\u000a\u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0438 \u0432 \u0440\u0430\u0437\u043c\u0435\u0440\u0435 $3 \u043c\u043b\u0440\u0434, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u043d\u0430\u043f\u0440\u0430\u0432\u0438\u0442 \u000d\u000a\u043d\u0430 \u043a\u043b\u044e\u0447\u0435\u0432\u044b\u0435 \u043f\u0440\u043e\u0435\u043a\u0442\u044b, \u0432\u043a\u043b\u044e\u0447\u0430\u044f \u0440\u0430\u0437\u0432\u0438\u0442\u0438\u0435 \u000d\u000a\u0414\u0436\u0435\u0431\u0435\u043b\u044c \u0410\u043b\u0438.\u000d\u000a03 11","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 20\u201327 \u043c\u0430\u0440\u0442\u0430 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0430 #\u0440\u0435\u0441\u0443\u0440\u0441\u044b #\u043b\u043e\u0433\u0438\u0441\u0442\u0438\u043a\u0430 #\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b\u000d\u000a\u042d\u043a\u0441\u043f\u043e\u0440\u0442 \u043d\u0435\u0444\u0442\u0438 \u0441 \u0411\u043b\u0438\u0436\u043d\u0435\u0433\u043e \u0412\u043e\u0441\u0442\u043e\u043a\u0430 \u0441\u043e\u043a\u0440\u0430\u0442\u0438\u043b\u0441\u044f \u000d\u000a\u0431\u043e\u043b\u0435\u0435 \u0447\u0435\u043c \u043d\u0430 60% \u043d\u0430 \u0444\u043e\u043d\u0435 \u0431\u043b\u043e\u043a\u0430\u0434\u044b \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u043e\u0433\u043e \u000d\u000a\u043f\u0440\u043e\u043b\u0438\u0432\u0430\u000d\u000a\u0411\u043b\u043e\u043a\u0430\u0434\u0430 \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u043e\u0433\u043e \u043f\u0440\u043e\u043b\u0438\u0432\u0430 \u2014 \u043a\u043b\u044e\u0447\u0435\u0432\u043e\u0439 \u0430\u0440\u0442\u0435\u0440\u0438\u0438, \u0447\u0435\u0440\u0435\u0437 \u043a\u043e\u0442\u043e\u0440\u0443\u044e \u043f\u0440\u043e\u0445\u043e\u0434\u0438\u0442 \u043e\u043a\u043e\u043b\u043e 20% \u000d\u000a\u043c\u0438\u0440\u043e\u0432\u044b\u0445 \u043f\u043e\u0441\u0442\u0430\u0432\u043e\u043a \u043d\u0435\u0444\u0442\u0438, \u2014 \u0432\u044b\u043d\u0443\u0434\u0438\u043b\u043e \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u0435\u0440\u043e\u0432 \u043e\u0442\u043c\u0435\u043d\u044f\u0442\u044c \u043e\u0442\u0433\u0440\u0443\u0437\u043a\u0438 \u0438 \u043e\u0441\u0442\u0430\u043d\u0430\u0432\u043b\u0438\u0432\u0430\u0442\u044c \u000d\u000a\u0434\u043e\u0431\u044b\u0447\u0443 \u043d\u0430 \u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u044f\u0445.\u000d\u000a\u042d\u043a\u0441\u043f\u043e\u0440\u0442 \u043d\u0435\u0444\u0442\u0438 \u0438\u0437 \u0441\u0442\u0440\u0430\u043d \u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u0433\u043e \u0437\u0430\u043b\u0438\u0432\u0430 \u000d\u000a\u0441\u043e\u043a\u0440\u0430\u0442\u0438\u043b\u0441\u044f \u043a\u0430\u043a \u043c\u0438\u043d\u0438\u043c\u0443\u043c \u043d\u0430 60% \u043f\u043e \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044e \u000d\u000a\u0441 \u0444\u0435\u0432\u0440\u0430\u043b\u0435\u043c \u043d\u0430 \u0444\u043e\u043d\u0435 \u0432\u043e\u0435\u043d\u043d\u043e\u0433\u043e \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u0430 \u000d\u000a\u0432 \u0440\u0435\u0433\u0438\u043e\u043d\u0435 \u0438 \u0444\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u0437\u0430\u043a\u0440\u044b\u0442\u0438\u044f \u000d\u000a\u041e\u0440\u043c\u0443\u0437\u0441\u043a\u043e\u0433\u043e \u043f\u0440\u043e\u043b\u0438\u0432\u0430. \u041e\u0431 \u044d\u0442\u043e\u043c \u0441\u043e\u043e\u0431\u0449\u0438\u043b\u043e \u000d\u000a\u0430\u0433\u0435\u043d\u0442\u0441\u0442\u0432\u043e Reuters \u0441\u043e \u0441\u0441\u044b\u043b\u043a\u043e\u0439 \u043d\u0430 \u0438\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0438\u044e \u000d\u000a\u0441\u0435\u0440\u0432\u0438\u0441\u043e\u0432 \u0434\u043b\u044f \u043e\u0442\u0441\u043b\u0435\u0436\u0438\u0432\u0430\u043d\u0438\u044f \u0441\u0443\u0434\u043e\u0432.\u000a\u000d\u000a\u041f\u043e \u0434\u0430\u043d\u043d\u044b\u043c \u0430\u043d\u0430\u043b\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 Kpler, \u000d\u000a\u0441\u043e\u0432\u043e\u043a\u0443\u043f\u043d\u044b\u0439 \u044d\u043a\u0441\u043f\u043e\u0440\u0442 \u043d\u0435\u0444\u0442\u0438, \u043a\u043e\u043d\u0434\u0435\u043d\u0441\u0430\u0442\u0430 \u0438 \u000d\u000a\u043d\u0435\u0444\u0442\u0435\u043f\u0440\u043e\u0434\u0443\u043a\u0442\u043e\u0432 \u0438\u0437 \u0432\u043e\u0441\u044c\u043c\u0438 \u0441\u0442\u0440\u0430\u043d \u0440\u0435\u0433\u0438\u043e\u043d\u0430 \u2014 \u000d\u000a\u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0439 \u0410\u0440\u0430\u0432\u0438\u0438, \u041a\u0443\u0432\u0435\u0439\u0442\u0430, \u0418\u0440\u0430\u043d\u0430, \u0418\u0440\u0430\u043a\u0430, \u000d\u000a\u041e\u043c\u0430\u043d\u0430, \u041a\u0430\u0442\u0430\u0440\u0430, \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0430 \u0438 \u041e\u0410\u042d \u2014 \u0437\u0430 \u0432\u0442\u043e\u0440\u0443\u044e \u000d\u000a\u043d\u0435\u0434\u0435\u043b\u044e \u043c\u0430\u0440\u0442\u0430 \u0441\u043e\u0441\u0442\u0430\u0432\u0438\u043b \u0432 \u0441\u0440\u0435\u0434\u043d\u0435\u043c \u2028\u000d\u000a9,71 \u043c\u043b\u043d \u0431\u0430\u0440\u0440\u0435\u043b\u0435\u0439 \u0432 \u0441\u0443\u0442\u043a\u0438.\u000d\u000a\u0424\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u043e\u0431\u044a\u0435\u043c\u044b \u043f\u043e\u0441\u0442\u0430\u0432\u043e\u043a \u043c\u043e\u0433\u0443\u0442 \u0431\u044b\u0442\u044c \u000d\u000a\u0435\u0449\u0435 \u043d\u0438\u0436\u0435, \u043f\u043e\u0441\u043a\u043e\u043b\u044c\u043a\u0443 \u0447\u0430\u0441\u0442\u044c \u043d\u0435\u0444\u0442\u0438 \u000d\u000a\u043d\u0430\u043f\u0440\u0430\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u0432 \u043f\u043b\u0430\u0432\u0443\u0447\u0438\u0435 \u0445\u0440\u0430\u043d\u0438\u043b\u0438\u0449\u0430 \u000d\u000a\u0438 \u043d\u0435 \u043f\u043e\u043a\u0438\u0434\u0430\u0435\u0442 \u0440\u0435\u0433\u0438\u043e\u043d. \u041f\u043e \u043e\u0446\u0435\u043d\u043a\u0435 Kpler, \u000d\u000a\u043e\u0431\u044a\u0435\u043c\u044b \u0442\u0430\u043a\u043e\u0439 \u043d\u0435\u0444\u0442\u0438 \u043f\u0440\u0435\u0432\u044b\u0441\u0438\u043b\u0438 \u2028\u000d\u000a50 \u043c\u043b\u043d \u0431\u0430\u0440\u0440\u0435\u043b\u0435\u0439 \u043f\u0440\u043e\u0442\u0438\u0432 \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u2028\u000d\u000a10 \u043c\u043b\u043d \u0431\u0430\u0440\u0440\u0435\u043b\u0435\u0439 \u0434\u043e \u043d\u0430\u0447\u0430\u043b\u0430 \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u0430.\u000a\u000d\u000a\u0421\u0442\u0440\u0430\u043d\u044b \u0411\u043b\u0438\u0436\u043d\u0435\u0433\u043e \u0412\u043e\u0441\u0442\u043e\u043a\u0430 \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0438\u0432\u0430\u043b\u0438 \u000d\u000a\u043e\u043a\u043e\u043b\u043e 36% \u043c\u0438\u0440\u043e\u0432\u043e\u0433\u043e \u043c\u043e\u0440\u0441\u043a\u043e\u0433\u043e \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u0430 \u000d\u000a\u043d\u0435\u0444\u0442\u0438, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u043e\u0446\u0435\u043d\u0438\u0432\u0430\u043b\u0441\u044f \u0432 70,43 \u043c\u043b\u043d \u000d\u000a\u0431\u0430\u0440\u0440\u0435\u043b\u0435\u0439 \u0432 \u0441\u0443\u0442\u043a\u0438. \u0427\u0430\u0441\u0442\u0438\u0447\u043d\u043e \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0438 \u000d\u000a\u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0430\u044e\u0442\u0441\u044f \u0447\u0435\u0440\u0435\u0437 \u0430\u043b\u044c\u0442\u0435\u0440\u043d\u0430\u0442\u0438\u0432\u043d\u044b\u0435 \u000d\u000a\u043c\u0430\u0440\u0448\u0440\u0443\u0442\u044b, \u0432\u043a\u043b\u044e\u0447\u0430\u044f \u0441\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0438\u0439 \u043f\u043e\u0440\u0442 \u042f\u043d\u0431\u0443 \u000d\u000a\u043d\u0430 \u0431\u0435\u0440\u0435\u0433\u0443 \u041a\u0440\u0430\u0441\u043d\u043e\u0433\u043e \u043c\u043e\u0440\u044f.\u000d\u000a04 11","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 20\u201327 \u043c\u0430\u0440\u0442\u0430 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u0442\u0435\u0445\u043d\u043e\u043b\u043e\u0433\u0438\u0438 #\u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0430 #\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b\u000d\u000a\u0420\u0430\u0431\u043e\u0442\u0430 \u043e\u0431\u043b\u0430\u0447\u043d\u044b\u0445 \u0441\u0435\u0440\u0432\u0438\u0441\u043e\u0432 Amazon \u043d\u0430\u0440\u0443\u0448\u0435\u043d\u0430 \u000d\u000a\u0432 \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0435 \u0438\u0437-\u0437\u0430 \u0434\u0440\u043e\u043d\u043e\u0432\u000d\u000aAmazon Web Services \u2014 \u043a\u043b\u044e\u0447\u0435\u0432\u043e\u0435 \u043f\u043e\u0434\u0440\u0430\u0437\u0434\u0435\u043b\u0435\u043d\u0438\u0435 Amazon, \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0438\u0432\u0430\u044e\u0449\u0435\u0435 \u0440\u0430\u0431\u043e\u0442\u0443 \u000d\u000a\u043c\u0435\u0436\u0434\u0443\u043d\u0430\u0440\u043e\u0434\u043d\u044b\u0445 \u043e\u043d\u043b\u0430\u0439\u043d-\u0441\u0435\u0440\u0432\u0438\u0441\u043e\u0432, \u043a\u043e\u0440\u043f\u043e\u0440\u0430\u0442\u0438\u0432\u043d\u044b\u0445 \u0441\u0438\u0441\u0442\u0435\u043c \u0438 \u0433\u043e\u0441\u043f\u043b\u0430\u0442\u0444\u043e\u0440\u043c, \u0430 \u0442\u0430\u043a\u0436\u0435 \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u0439 \u000d\u000a\u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a \u043f\u0440\u0438\u0431\u044b\u043b\u0438 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438.\u000d\u000a\u0410\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u0430\u044f \u043a\u043e\u0440\u043f\u043e\u0440\u0430\u0446\u0438\u044f Amazon \u000d\u000a\u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043b\u0430 \u043d\u0430\u0440\u0443\u0448\u0435\u043d\u0438\u044f \u0432 \u0440\u0430\u0431\u043e\u0442\u0435 \u0441\u0432\u043e\u0438\u0445 \u000d\u000a\u043e\u0431\u043b\u0430\u0447\u043d\u044b\u0445 \u0441\u0435\u0440\u0432\u0438\u0441\u043e\u0432 Amazon Web Services (AWS) \u000d\u000a\u0432 \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0435 \u043d\u0430 \u0444\u043e\u043d\u0435 \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0430\u044e\u0449\u0435\u0433\u043e\u0441\u044f \u000d\u000a\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u0430 \u043d\u0430 \u0411\u043b\u0438\u0436\u043d\u0435\u043c \u0412\u043e\u0441\u0442\u043e\u043a\u0435. \u041f\u0440\u0438\u0447\u0438\u043d\u043e\u0439 \u000d\u000a\u0441\u0431\u043e\u0435\u0432 \u0441\u0442\u0430\u043b\u0430 \u0430\u043a\u0442\u0438\u0432\u043d\u043e\u0441\u0442\u044c \u0431\u0435\u0441\u043f\u0438\u043b\u043e\u0442\u043d\u0438\u043a\u043e\u0432 \u0432 \u0440\u0430\u0439\u043e\u043d\u0435 \u000d\u000a\u0440\u0430\u0437\u043c\u0435\u0449\u0435\u043d\u0438\u044f \u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u044b, \u0441\u043e\u043e\u0431\u0449\u0438\u043b\u0430 \u000d\u000a\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f.\u000a\u000d\u000a\u042d\u0442\u043e \u0443\u0436\u0435 \u0432\u0442\u043e\u0440\u043e\u0439 \u0441\u043b\u0443\u0447\u0430\u0439 \u0437\u0430 \u043c\u0435\u0441\u044f\u0446, \u043a\u043e\u0433\u0434\u0430 \u000d\u000a\u043e\u043f\u0435\u0440\u0430\u0446\u0438\u0438 AWS \u0432 \u0440\u0435\u0433\u0438\u043e\u043d\u0435 \u043e\u043a\u0430\u0437\u044b\u0432\u0430\u044e\u0442\u0441\u044f \u000d\u000a\u0437\u0430\u0442\u0440\u043e\u043d\u0443\u0442\u044b \u0432\u043e\u0435\u043d\u043d\u044b\u043c\u0438 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f\u043c\u0438. \u000d\u000a\u041f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u044c Amazon \u0441\u043e\u043e\u0431\u0449\u0438\u043b, \u0447\u0442\u043e \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u000d\u000a\u043f\u043e\u043c\u043e\u0433\u0430\u0435\u0442 \u043a\u043b\u0438\u0435\u043d\u0442\u0430\u043c \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0438\u0442\u044c \u043d\u0430\u0433\u0440\u0443\u0437\u043a\u0443 \u000d\u000a\u0432 \u0434\u0440\u0443\u0433\u0438\u0435 \u0440\u0435\u0433\u0438\u043e\u043d\u044b AWS, \u043e\u0434\u043d\u0430\u043a\u043e \u043d\u0435 \u0441\u0442\u0430\u043b \u000d\u000a\u0440\u0430\u0441\u043a\u0440\u044b\u0432\u0430\u0442\u044c \u043c\u0430\u0441\u0448\u0442\u0430\u0431 \u043f\u043e\u0432\u0440\u0435\u0436\u0434\u0435\u043d\u0438\u0439 \u0438 \u0441\u0440\u043e\u043a\u0438 \u000d\u000a\u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u044f.\u000d\u000a\u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u0442\u0430\u043a\u0436\u0435 \u043d\u0435 \u0443\u0442\u043e\u0447\u043d\u0438\u043b\u0430, \u043f\u043e\u0434\u0432\u0435\u0440\u0433\u0441\u044f \u043b\u0438 \u2028\u000d\u000a\u043e\u0431\u044a\u0435\u043a\u0442 \u043f\u0440\u044f\u043c\u043e\u043c\u0443 \u0443\u0434\u0430\u0440\u0443 \u0434\u0440\u043e\u043d\u043e\u0432 \u0438\u043b\u0438 \u043f\u0435\u0440\u0435\u0431\u043e\u0438 \u000d\u000a\u0432\u044b\u0437\u0432\u0430\u043d\u044b \u0430\u0442\u0430\u043a\u0430\u043c\u0438 \u043f\u043e\u0431\u043b\u0438\u0437\u043e\u0441\u0442\u0438. \u041f\u0440\u0438 \u044d\u0442\u043e\u043c \u000d\u000a\u043d\u0430 \u043c\u043e\u043c\u0435\u043d\u0442 \u0432\u0435\u0447\u0435\u0440\u0430 \u043f\u043e\u043d\u0435\u0434\u0435\u043b\u044c\u043d\u0438\u043a\u0430 \u0438\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0438\u044f \u000d\u000a\u043e \u0441\u0431\u043e\u0435 \u043d\u0435 \u0431\u044b\u043b\u0430 \u043e\u0442\u0440\u0430\u0436\u0435\u043d\u0430 \u043d\u0430 \u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u043e\u0439 \u000d\u000a\u0441\u0442\u0440\u0430\u043d\u0438\u0446\u0435 \u0441\u0442\u0430\u0442\u0443\u0441\u0430 AWS.\u000a\u000d\u000a\u0420\u0430\u043d\u0435\u0435 \u043e\u0431\u044a\u0435\u043a\u0442\u044b AWS \u0432 \u041e\u0410\u042d \u0438 \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0435 \u000d\u000a\u0441\u0442\u043e\u043b\u043a\u043d\u0443\u043b\u0438\u0441\u044c \u0441 \u043e\u0442\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u044f\u043c\u0438 \u044d\u043b\u0435\u043a\u0442\u0440\u043e\u044d\u043d\u0435\u0440\u0433\u0438\u0438 \u000d\u000a\u043f\u043e\u0441\u043b\u0435 \u0443\u0434\u0430\u0440\u043e\u0432, \u0447\u0442\u043e \u043f\u043e\u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043b\u043e \u0441\u0440\u043e\u0447\u043d\u043e\u0433\u043e \u000d\u000a\u043f\u0435\u0440\u0435\u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044f \u0432\u044b\u0447\u0438\u0441\u043b\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0445 \u000d\u000a\u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0435\u0439. \u041f\u043e\u0432\u0440\u0435\u0436\u0434\u0435\u043d\u0438\u0435 \u043e\u0431\u044a\u0435\u043a\u0442\u0430 \u0432 \u041e\u0410\u042d \u0441\u0442\u0430\u043b\u043e \u000d\u000a\u043f\u0435\u0440\u0432\u044b\u043c \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u044b\u043c \u0441\u043b\u0443\u0447\u0430\u0435\u043c, \u043a\u043e\u0433\u0434\u0430 \u0432\u043e\u0435\u043d\u043d\u044b\u0435 \u000d\u000a\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f \u043d\u0430\u043f\u0440\u044f\u043c\u0443\u044e \u043f\u043e\u0432\u043b\u0438\u044f\u043b\u0438 \u043d\u0430 \u0434\u0430\u0442\u0430-\u0446\u0435\u043d\u0442\u0440 \u000d\u000a\u043a\u0440\u0443\u043f\u043d\u043e\u0439 \u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u043e\u0439 \u0442\u0435\u0445\u043d\u043e\u043b\u043e\u0433\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u000d\u000a\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438.\u000d\u000a05 11","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 20\u201327 \u043c\u0430\u0440\u0442\u0430 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b #\u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0430 #\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b\u000d\u000a\u0418\u0440\u0430\u043d\u0441\u043a\u0438\u0435 \u0430\u0442\u0430\u043a\u0438 \u0432\u044b\u0432\u0435\u043b\u0438 \u0438\u0437 \u0441\u0442\u0440\u043e\u044f 17% \u043a\u0430\u0442\u0430\u0440\u0441\u043a\u0438\u0445 \u000d\u000a\u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0435\u0439 \u043f\u043e \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0443 \u0421\u041f\u0413\u000d\u000a\u041a\u0430\u0442\u0430\u0440 \u0443\u0436\u0435 \u043e\u0431\u044a\u044f\u0432\u0438\u043b \u0444\u043e\u0440\u0441-\u043c\u0430\u0436\u043e\u0440 \u043f\u043e \u0434\u043e\u043b\u0433\u043e\u0441\u0440\u043e\u0447\u043d\u044b\u043c \u043a\u043e\u043d\u0442\u0440\u0430\u043a\u0442\u0430\u043c \u043d\u0430 \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0438 \u0433\u0430\u0437\u0430, \u0437\u0430\u0442\u0440\u043e\u043d\u0443\u0432\u0448\u0438\u0439 \u000d\u000a\u0438\u043c\u043f\u043e\u0440\u0442\u0435\u0440\u043e\u0432 \u0432 \u0418\u0442\u0430\u043b\u0438\u0438, \u0411\u0435\u043b\u044c\u0433\u0438\u0438, \u042e\u0436\u043d\u043e\u0439 \u041a\u043e\u0440\u0435\u0435 \u0438 \u041a\u0438\u0442\u0430\u0435. \u000d\u000a\u0418\u0440\u0430\u043d\u0441\u043a\u0438\u0435 \u0430\u0442\u0430\u043a\u0438 \u043d\u0430 \u044d\u043d\u0435\u0440\u0433\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u0443\u044e \u000d\u000a\u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0443 \u041a\u0430\u0442\u0430\u0440\u0430 \u043f\u0440\u0438\u0432\u0435\u043b\u0438 \u043a \u043e\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0435 \u000d\u000a\u043f\u043e\u0440\u044f\u0434\u043a\u0430 17% \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0435\u0439 \u043f\u043e \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0443 \u000d\u000a\u0441\u0436\u0438\u0436\u0435\u043d\u043d\u043e\u0433\u043e \u043f\u0440\u0438\u0440\u043e\u0434\u043d\u043e\u0433\u043e \u0433\u0430\u0437\u0430 (\u0421\u041f\u0413), \u0447\u0442\u043e \u043c\u043e\u0436\u0435\u0442 \u000d\u000a\u0432\u044b\u0437\u0432\u0430\u0442\u044c \u0435\u0436\u0435\u0433\u043e\u0434\u043d\u044b\u0435 \u043f\u043e\u0442\u0435\u0440\u0438 \u043d\u0430 \u0443\u0440\u043e\u0432\u043d\u0435 \u2028\u000d\u000a$20 \u043c\u043b\u0440\u0434 \u0438 \u0441\u043e\u0437\u0434\u0430\u0442\u044c \u0440\u0438\u0441\u043a\u0438 \u0434\u043b\u044f \u043f\u043e\u0441\u0442\u0430\u0432\u043e\u043a \u000d\u000a\u0432 \u0415\u0432\u0440\u043e\u043f\u0443 \u0438 \u0410\u0437\u0438\u044e. \u041e\u0431 \u044d\u0442\u043e\u043c \u0432 \u0438\u043d\u0442\u0435\u0440\u0432\u044c\u044e Reuters \u000d\u000a\u0437\u0430\u044f\u0432\u0438\u043b \u0433\u043b\u0430\u0432\u0430 QatarEnergy \u0421\u0430\u0430\u0434 \u0430\u043b\u044c-\u041a\u0430\u0430\u0431\u0438.\u000a\u000d\u000a\u041f\u043e \u0435\u0433\u043e \u0441\u043b\u043e\u0432\u0430\u043c, \u0432 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0435 \u0430\u0442\u0430\u043a \u0431\u044b\u043b\u0438 \u000d\u000a\u043f\u043e\u0432\u0440\u0435\u0436\u0434\u0435\u043d\u044b \u0434\u0432\u0435 \u0438\u0437 \u0447\u0435\u0442\u044b\u0440\u043d\u0430\u0434\u0446\u0430\u0442\u0438 \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0445 \u043b\u0438\u043d\u0438\u0439 \u043f\u043e \u0441\u0436\u0438\u0436\u0435\u043d\u0438\u044e \u0433\u0430\u0437\u0430.\u2028\u000d\u000a\u0415\u0436\u0435\u0433\u043e\u0434\u043d\u043e\u0435 \u0441\u043d\u0438\u0436\u0435\u043d\u0438\u0435 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u0421\u041f\u0413 \u000d\u000a\u0441\u043e\u0441\u0442\u0430\u0432\u0438\u0442 \u043e\u043a\u043e\u043b\u043e 12,8 \u043c\u043b\u043d \u0442\u043e\u043d\u043d. \u0412\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u0435\u000d\u000a\u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0435\u0439 \u0434\u043e \u043f\u0440\u0435\u0436\u043d\u0435\u0433\u043e \u043e\u0431\u044a\u0435\u043c\u0430 \u0437\u0430\u0439\u043c\u0435\u0442 \u000d\u000a\u043e\u0442 \u0442\u0440\u0435\u0445 \u0434\u043e \u043f\u044f\u0442\u0438 \u043b\u0435\u0442.\u000a\u000d\u000a\u041d\u0435\u0433\u0430\u0442\u0438\u0432\u043d\u044b\u0435 \u043f\u043e\u0441\u043b\u0435\u0434\u0441\u0442\u0432\u0438\u044f \u0437\u0430\u0442\u0440\u043e\u043d\u0443\u0442 \u043d\u0435 \u0442\u043e\u043b\u044c\u043a\u043e \u000d\u000a\u0440\u044b\u043d\u043e\u043a \u0421\u041f\u0413. \u042d\u043a\u0441\u043f\u043e\u0440\u0442 \u0433\u0430\u0437\u043e\u0432\u043e\u0433\u043e \u043a\u043e\u043d\u0434\u0435\u043d\u0441\u0430\u0442\u0430 \u000d\u000a\u0438\u0437 \u041a\u0430\u0442\u0430\u0440\u0430 \u0441\u043e\u043a\u0440\u0430\u0442\u0438\u0442\u0441\u044f \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u043d\u0430 24%, \u000d\u000a\u0441\u0436\u0438\u0436\u0435\u043d\u043d\u043e\u0433\u043e \u043d\u0435\u0444\u0442\u044f\u043d\u043e\u0433\u043e \u0433\u0430\u0437\u0430 \u2014 \u043d\u0430 13%, \u0433\u0435\u043b\u0438\u044f \u2014 \u000d\u000a\u043d\u0430 14%. \u042d\u0442\u043e \u043c\u043e\u0436\u0435\u0442 \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u043e \u043f\u043e\u0432\u043b\u0438\u044f\u0442\u044c \u000d\u000a\u043d\u0430 \u0446\u0435\u043b\u044b\u0439 \u0440\u044f\u0434 \u043e\u0442\u0440\u0430\u0441\u043b\u0435\u0439 \u2014 \u043e\u0442 \u0440\u0435\u0441\u0442\u043e\u0440\u0430\u043d\u043d\u043e\u0433\u043e \u000d\u000a\u0431\u0438\u0437\u043d\u0435\u0441\u0430 \u0432 \u0418\u043d\u0434\u0438\u0438 \u0434\u043e \u044e\u0436\u043d\u043e\u043a\u043e\u0440\u0435\u0439\u0441\u043a\u043e\u0433\u043e \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u043f\u043e\u043b\u0443\u043f\u0440\u043e\u0432\u043e\u0434\u043d\u0438\u043a\u043e\u0432, \u000d\u000a\u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u044e\u0449\u0435\u0433\u043e \u0433\u0435\u043b\u0438\u0439.\u000d\u000a#\u0432\u043e\u043e\u0440\u0443\u0436\u0435\u043d\u0438\u0435 #\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b\u000d\u000a\u0421\u0428\u0410 \u043e\u0434\u043e\u0431\u0440\u0438\u043b\u0438 \u0434\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0438 \u000d\u000a\u0432\u043e\u043e\u0440\u0443\u0436\u0435\u043d\u0438\u044f \u041e\u0410\u042d \u043d\u0430 $7 \u043c\u043b\u0440\u0434\u000d\u000a\u0420\u0430\u0441\u0448\u0438\u0440\u0435\u043d\u0438\u0435 \u0432\u043e\u0435\u043d\u043d\u043e-\u0442\u0435\u0445\u043d\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u0441\u043e\u0442\u0440\u0443\u0434\u043d\u0438\u0447\u0435\u0441\u0442\u0432\u0430 \u043f\u0440\u043e\u0438\u0441\u0445\u043e\u0434\u0438\u0442 \u043d\u0430 \u0444\u043e\u043d\u0435 \u043e\u0431\u043e\u0441\u0442\u0440\u0435\u043d\u0438\u044f \u000d\u000a\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u0430 \u0432\u043e\u043a\u0440\u0443\u0433 \u0418\u0440\u0430\u043d\u0430. \u041f\u043e\u0441\u0442\u0430\u0432\u043a\u0438 \u0441\u0438\u0441\u0442\u0435\u043c \u041f\u0412\u041e \u0438 \u0442\u0440\u0430\u043d\u0441\u043f\u043e\u0440\u0442\u043d\u044b\u0445 \u0432\u0435\u0440\u0442\u043e\u043b\u0435\u0442\u043e\u0432 \u0443\u0441\u0438\u043b\u044f\u0442 \u000d\u000a\u043e\u0431\u043e\u0440\u043e\u043d\u043d\u044b\u0439 \u043f\u043e\u0442\u0435\u043d\u0446\u0438\u0430\u043b \u041e\u0410\u042d \u0432 \u0443\u0441\u043b\u043e\u0432\u0438\u044f\u0445 \u0440\u043e\u0441\u0442\u0430 \u043d\u0430\u043f\u0440\u044f\u0436\u0435\u043d\u043d\u043e\u0441\u0442\u0438 \u0432 \u0440\u0435\u0433\u0438\u043e\u043d\u0435.\u000d\u000a\u0410\u0434\u043c\u0438\u043d\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u044f \u0421\u0428\u0410 \u043e\u0434\u043e\u0431\u0440\u0438\u043b\u0430 \u000d\u000a\u0434\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0438 \u0432\u043e\u043e\u0440\u0443\u0436\u0435\u043d\u0438\u044f \u0434\u043b\u044f \u000d\u000a\u041e\u0410\u042d \u043d\u0430 \u0441\u0443\u043c\u043c\u0443 \u043e\u043a\u043e\u043b\u043e $7 \u043c\u043b\u0440\u0434, \u043d\u0435 \u043f\u043e\u0434\u043b\u0435\u0436\u0430\u0449\u0438\u0435 \u000d\u000a\u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u043c\u0443 \u043f\u0443\u0431\u043b\u0438\u0447\u043d\u043e\u043c\u0443 \u0440\u0430\u0441\u043a\u0440\u044b\u0442\u0438\u044e \u000d\u000a\u0432 \u0440\u0430\u043c\u043a\u0430\u0445 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044e\u0449\u0438\u0445 \u043f\u0440\u0430\u0432\u0438\u043b \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u0430 \u000d\u000a\u043e\u0440\u0443\u0436\u0438\u044f. \u041e\u0431 \u044d\u0442\u043e\u043c \u0441\u043e\u043e\u0431\u0449\u0430\u0435\u0442 The Wall Street \u000d\u000aJournal.\u000a\u000d\u000a\u0420\u0435\u0447\u044c \u0438\u0434\u0435\u0442 \u043e \u0441\u0434\u0435\u043b\u043a\u0430\u0445, \u0440\u0430\u0441\u0448\u0438\u0440\u044f\u044e\u0449\u0438\u0445 \u000d\u000a\u0437\u0430\u043a\u043b\u044e\u0447\u0435\u043d\u043d\u044b\u0435 \u0440\u0430\u043d\u0435\u0435 \u0441\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u044f. \u0412 \u0438\u0445 \u0447\u0438\u0441\u043b\u0435 \u2014 \u000d\u000a\u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0430 \u0437\u0435\u043d\u0438\u0442\u043d\u044b\u0445 \u0440\u0430\u043a\u0435\u0442\u043d\u044b\u0445 \u043a\u043e\u043c\u043f\u043b\u0435\u043a\u0441\u043e\u0432 Patriot \u000d\u000aPAC-3 \u043d\u0430 \u0441\u0443\u043c\u043c\u0443 \u043e\u043a\u043e\u043b\u043e $5,6 \u043c\u043b\u0440\u0434, \u0430 \u0442\u0430\u043a\u0436\u0435 \u000d\u000a\u0432\u0435\u0440\u0442\u043e\u043b\u0435\u0442\u043e\u0432 CH-47 Chinook \u0441\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u044c\u044e \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u000d\u000a$1,32 \u043c\u043b\u0440\u0434.\u000a\u000d\u000a\u041f\u043e \u0434\u0430\u043d\u043d\u044b\u043c \u0438\u0437\u0434\u0430\u043d\u0438\u044f, \u043d\u043e\u0432\u044b\u0435 \u0441\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u044f \u043d\u0435 \u0431\u044b\u043b\u0438 \u000d\u000a\u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u043e \u0430\u043d\u043e\u043d\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u044b, \u043f\u043e\u0441\u043a\u043e\u043b\u044c\u043a\u0443 \u000d\u000a\u0444\u043e\u0440\u043c\u0430\u043b\u044c\u043d\u043e \u0441\u0447\u0438\u0442\u0430\u044e\u0442\u0441\u044f \u0440\u0430\u0441\u0448\u0438\u0440\u0435\u043d\u0438\u0435\u043c \u0443\u0436\u0435 \u000d\u000a\u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044e\u0449\u0438\u0445 \u043a\u043e\u043d\u0442\u0440\u0430\u043a\u0442\u043e\u0432 \u0438 \u043d\u0435 \u0442\u0440\u0435\u0431\u0443\u044e\u0442 \u000d\u000a\u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e\u0433\u043e \u0443\u0432\u0435\u0434\u043e\u043c\u043b\u0435\u043d\u0438\u044f \u043e\u0431\u0449\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0441\u0442\u0438.\u000d\u000a06 11","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 20\u201327 \u043c\u0430\u0440\u0442\u0430 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0430 #\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b\u000d\u000a\u0411\u0430\u0445\u0440\u0435\u0439\u043d \u043f\u0440\u043e\u0434\u0432\u0438\u0433\u0430\u0435\u0442 \u0432 \u0421\u0411 \u041e\u041e\u041d \u0440\u0435\u0437\u043e\u043b\u044e\u0446\u0438\u044e \u043e \u0437\u0430\u0449\u0438\u0442\u0435 \u000d\u000a\u0441\u0443\u0434\u043e\u0445\u043e\u0434\u0441\u0442\u0432\u0430 \u0432 \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u043e\u043c \u043f\u0440\u043e\u043b\u0438\u0432\u0435\u000d\u000a\u0418\u043d\u0438\u0446\u0438\u0430\u0442\u0438\u0432\u0430 \u043e\u0442\u0440\u0430\u0436\u0430\u0435\u0442 \u0440\u0430\u0441\u0442\u0443\u0449\u0443\u044e \u043e\u0431\u0435\u0441\u043f\u043e\u043a\u043e\u0435\u043d\u043d\u043e\u0441\u0442\u044c \u0440\u0435\u0433\u0438\u043e\u043d\u0430 \u0442\u0435\u043c, \u0447\u0442\u043e \u0418\u0440\u0430\u043d \u043c\u043e\u0436\u0435\u0442 \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0438\u0442\u044c \u000d\u000a\u0430\u0442\u0430\u043a\u0438 \u043d\u0430 \u0441\u0443\u0434\u0430 \u0432 \u0441\u0442\u0440\u0430\u0442\u0435\u0433\u0438\u0447\u0435\u0441\u043a\u0438 \u0432\u0430\u0436\u043d\u043e\u043c \u043f\u0440\u043e\u043b\u0438\u0432\u0435, \u0447\u0435\u0440\u0435\u0437 \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u043f\u0440\u043e\u0445\u043e\u0434\u0438\u0442 \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u043f\u044f\u0442\u0430\u044f \u000d\u000a\u0447\u0430\u0441\u0442\u044c \u043c\u0438\u0440\u043e\u0432\u044b\u0445 \u043f\u043e\u0441\u0442\u0430\u0432\u043e\u043a \u043d\u0435\u0444\u0442\u0438. \u041d\u0430 \u0444\u043e\u043d\u0435 \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u0430 \u0434\u0432\u0438\u0436\u0435\u043d\u0438\u0435 \u0441\u0443\u0434\u043e\u0432 \u0432 \u0430\u043a\u0432\u0430\u0442\u043e\u0440\u0438\u0438 \u043f\u0440\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u000d\u000a\u043e\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u043b\u043e\u0441\u044c.\u000d\u000a\u0427\u043b\u0435\u043d\u044b \u0421\u043e\u0432\u0435\u0442\u0430 \u0411\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u043e\u0441\u0442\u0438 \u041e\u041e\u041d \u043d\u0430\u0447\u0430\u043b\u0438 \u000d\u000a\u043e\u0431\u0441\u0443\u0436\u0434\u0430\u0442\u044c \u043f\u0440\u043e\u0435\u043a\u0442\u044b \u0440\u0435\u0437\u043e\u043b\u044e\u0446\u0438\u0439, \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043d\u044b\u0445 \u000d\u000a\u043d\u0430 \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0435\u043d\u0438\u0435 \u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u043e\u0441\u0442\u0438 \u043a\u043e\u043c\u043c\u0435\u0440\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u000d\u000a\u043f\u0440\u043e\u0445\u043e\u0434\u0430 \u0447\u0435\u0440\u0435\u0437 \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u0438\u0439 \u043f\u0440\u043e\u043b\u0438\u0432. \u041e\u0434\u0438\u043d \u000d\u000a\u0438\u0437 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u043e\u0432, \u043f\u043e\u0434\u0433\u043e\u0442\u043e\u0432\u043b\u0435\u043d\u043d\u044b\u0439 \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u043e\u043c \u000d\u000a\u043f\u0440\u0438 \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0435 \u0421\u0428\u0410 \u0438 \u0434\u0440\u0443\u0433\u0438\u0445 \u0441\u0442\u0440\u0430\u043d \u000d\u000a\u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u0433\u043e \u0437\u0430\u043b\u0438\u0432\u0430, \u043f\u0440\u0435\u0434\u0443\u0441\u043c\u0430\u0442\u0440\u0438\u0432\u0430\u0435\u0442 \u000d\u000a\u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e\u0441\u0442\u044c \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u044c \u00ab\u0432\u0441\u0435 \u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u044b\u0435 \u000d\u000a\u0441\u0440\u0435\u0434\u0441\u0442\u0432\u0430\u00bb \u0434\u043b\u044f \u0437\u0430\u0449\u0438\u0442\u044b \u043d\u0430\u0432\u0438\u0433\u0430\u0446\u0438\u0438.\u000a\u000d\u000a\u0421\u043e\u0433\u043b\u0430\u0441\u043d\u043e \u0442\u0435\u043a\u0441\u0442\u0443 \u043f\u0440\u043e\u0435\u043a\u0442\u0430, \u0441 \u043a\u043e\u0442\u043e\u0440\u044b\u043c \u000d\u000a\u043e\u0437\u043d\u0430\u043a\u043e\u043c\u0438\u043b\u043e\u0441\u044c \u0430\u0433\u0435\u043d\u0442\u0441\u0442\u0432\u043e Reuters, \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f \u000d\u000a\u0418\u0440\u0430\u043d\u0430 \u043a\u0432\u0430\u043b\u0438\u0444\u0438\u0446\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u043a\u0430\u043a \u0443\u0433\u0440\u043e\u0437\u0430 \u000d\u000a\u043c\u0435\u0436\u0434\u0443\u043d\u0430\u0440\u043e\u0434\u043d\u043e\u0439 \u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u043e\u0441\u0442\u0438. \u0414\u043e\u043a\u0443\u043c\u0435\u043d\u0442 \u000d\u000a\u043f\u0440\u0435\u0434\u043b\u0430\u0433\u0430\u0435\u0442 \u0440\u0430\u0437\u0440\u0435\u0448\u0438\u0442\u044c \u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0430\u043c \u2014 \u043a\u0430\u043a \u000d\u000a\u0441\u0430\u043c\u043e\u0441\u0442\u043e\u044f\u0442\u0435\u043b\u044c\u043d\u043e, \u0442\u0430\u043a \u0438 \u0432 \u0441\u043e\u0441\u0442\u0430\u0432\u0435 \u000d\u000a\u043c\u043d\u043e\u0433\u043e\u043d\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u044b\u0445 \u043a\u043e\u0430\u043b\u0438\u0446\u0438\u0439, \u2014 \u043f\u0440\u0438\u043c\u0435\u043d\u044f\u0442\u044c \u000d\u000a\u0441\u0438\u043b\u0443 \u0434\u043b\u044f \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0435\u043d\u0438\u044f \u0441\u0432\u043e\u0431\u043e\u0434\u044b \u0441\u0443\u0434\u043e\u0445\u043e\u0434\u0441\u0442\u0432\u0430, \u000d\u000a\u0432\u043a\u043b\u044e\u0447\u0430\u044f \u043e\u043f\u0435\u0440\u0430\u0446\u0438\u0438 \u0432 \u0442\u0435\u0440\u0440\u0438\u0442\u043e\u0440\u0438\u0430\u043b\u044c\u043d\u044b\u0445 \u0432\u043e\u0434\u0430\u0445 \u000d\u000a\u0441\u0442\u0440\u0430\u043d \u0440\u0435\u0433\u0438\u043e\u043d\u0430. \u0422\u0430\u043a\u0436\u0435 \u0434\u043e\u043f\u0443\u0441\u043a\u0430\u0435\u0442\u0441\u044f \u0432\u0432\u0435\u0434\u0435\u043d\u0438\u0435 \u000d\u000a\u0446\u0435\u043b\u0435\u0432\u044b\u0445 \u0441\u0430\u043d\u043a\u0446\u0438\u0439.\u000a\u000d\u000a\u0412 \u0442\u043e \u0436\u0435 \u0432\u0440\u0435\u043c\u044f \u0424\u0440\u0430\u043d\u0446\u0438\u044f \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u043b\u0430 \u000d\u000a\u0430\u043b\u044c\u0442\u0435\u0440\u043d\u0430\u0442\u0438\u0432\u043d\u044b\u0439, \u0431\u043e\u043b\u0435\u0435 \u0441\u0434\u0435\u0440\u0436\u0430\u043d\u043d\u044b\u0439 \u0432\u0430\u0440\u0438\u0430\u043d\u0442 \u000d\u000a\u0440\u0435\u0437\u043e\u043b\u044e\u0446\u0438\u0438, \u043d\u0435 \u043f\u0440\u0435\u0434\u0443\u0441\u043c\u0430\u0442\u0440\u0438\u0432\u0430\u044e\u0449\u0438\u0439 \u000d\u000a\u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u0438\u044f \u0441\u0438\u043b\u044b \u0438 \u043d\u0435 \u0443\u043f\u043e\u043c\u0438\u043d\u0430\u044e\u0449\u0438\u0439 \u0418\u0440\u0430\u043d \u000d\u000a\u043d\u0430\u043f\u0440\u044f\u043c\u0443\u044e. \u041f\u0430\u0440\u0438\u0436 \u043f\u0440\u0438\u0437\u044b\u0432\u0430\u0435\u0442 \u043a \u0434\u0435\u044d\u0441\u043a\u0430\u043b\u0430\u0446\u0438\u0438, \u000d\u000a\u043f\u0440\u0435\u043a\u0440\u0430\u0449\u0435\u043d\u0438\u044e \u0431\u043e\u0435\u0432\u044b\u0445 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0439 \u0432 \u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u043c \u000d\u000a\u0437\u0430\u043b\u0438\u0432\u0435 \u0438 \u0432\u043e\u0437\u0432\u0440\u0430\u0449\u0435\u043d\u0438\u044e \u043a \u0434\u0438\u043f\u043b\u043e\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u043c\u0443 \u000d\u000a\u0443\u0440\u0435\u0433\u0443\u043b\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044e. \u0414\u043e\u043a\u0443\u043c\u0435\u043d\u0442 \u0442\u0430\u043a\u0436\u0435 \u043f\u0440\u0435\u0434\u043b\u0430\u0433\u0430\u0435\u0442 \u000d\u000a\u043a\u043e\u043e\u0440\u0434\u0438\u043d\u0430\u0446\u0438\u044e \u0438\u0441\u043a\u043b\u044e\u0447\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u043e\u0431\u043e\u0440\u043e\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0445 \u000d\u000a\u043c\u0435\u0440, \u0432\u043a\u043b\u044e\u0447\u0430\u044f \u0441\u043e\u043f\u0440\u043e\u0432\u043e\u0436\u0434\u0435\u043d\u0438\u0435 \u0442\u043e\u0440\u0433\u043e\u0432\u044b\u0445 \u0441\u0443\u0434\u043e\u0432, \u000d\u000a\u043f\u0440\u0438 \u0441\u043e\u0431\u043b\u044e\u0434\u0435\u043d\u0438\u0438 \u043c\u0435\u0436\u0434\u0443\u043d\u0430\u0440\u043e\u0434\u043d\u043e\u0433\u043e \u043f\u0440\u0430\u0432\u0430.\u000a\u000d\u000a#\u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0430\u000d\u000a\u041c\u0418\u0414 \u0420\u0424 \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0430\u0435\u0442 \u043f\u043e\u0434\u0433\u043e\u0442\u043e\u0432\u043a\u0443 \u0432\u0438\u0437\u0438\u0442\u0430 \u041f\u0443\u0442\u0438\u043d\u0430 \u000d\u000a\u0432 \u041a\u0438\u0442\u0430\u0439 \u0432 \u043f\u0435\u0440\u0432\u043e\u0439 \u043f\u043e\u043b\u043e\u0432\u0438\u043d\u0435 \u0433\u043e\u0434\u0430\u000d\u000a\u0414\u0430\u0442\u044b \u0440\u0430\u0431\u043e\u0447\u0435\u0439 \u043f\u043e\u0435\u0437\u0434\u043a\u0438 \u043c\u043e\u0433\u0443\u0442 \u0431\u044b\u0442\u044c \u043e\u0431\u044a\u044f\u0432\u043b\u0435\u043d\u044b \u0432 \u0431\u043b\u0438\u0436\u0430\u0439\u0448\u0435\u0435 \u0432\u0440\u0435\u043c\u044f.\u000d\u000a\u0420\u043e\u0441\u0441\u0438\u0439\u0441\u043a\u043e\u0435 \u0432\u043d\u0435\u0448\u043d\u0435\u043f\u043e\u043b\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0435 \u0432\u0435\u0434\u043e\u043c\u0441\u0442\u0432\u043e \u000d\u000a\u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0430\u0435\u0442 \u043f\u0440\u043e\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u0442\u044c \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u0443 \u000d\u000a\u043f\u0440\u0435\u0434\u0441\u0442\u043e\u044f\u0449\u0435\u0433\u043e \u0432\u0438\u0437\u0438\u0442\u0430 \u043f\u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442\u0430 \u0420\u0424 \u0412\u043b\u0430\u0434\u0438\u043c\u0438\u0440\u0430 \u000d\u000a\u041f\u0443\u0442\u0438\u043d\u0430 \u0432 \u041a\u0438\u0442\u0430\u0439, \u0437\u0430\u044f\u0432\u0438\u043b \u0437\u0430\u043c\u0435\u0441\u0442\u0438\u0442\u0435\u043b\u044c \u043c\u0438\u043d\u0438\u0441\u0442\u0440\u0430 \u000d\u000a\u0438\u043d\u043e\u0441\u0442\u0440\u0430\u043d\u043d\u044b\u0445 \u0434\u0435\u043b \u0420\u043e\u0441\u0441\u0438\u0438 \u0410\u043d\u0434\u0440\u0435\u0439 \u0420\u0443\u0434\u0435\u043d\u043a\u043e.\u000a\u000d\u000a\u041e\u043d \u0434\u043e\u0431\u0430\u0432\u0438\u043b, \u0447\u0442\u043e \u0434\u0430\u0442\u044b \u043f\u043e\u0435\u0437\u0434\u043a\u0438 \u0433\u043b\u0430\u0432\u044b \u000d\u000a\u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0430 \u0432 \u041a\u041d\u0420 \u043c\u043e\u0433\u0443\u0442 \u0431\u044b\u0442\u044c \u043e\u0431\u044a\u044f\u0432\u043b\u0435\u043d\u044b \u000d\u000a\u0432 \u0431\u043b\u0438\u0436\u0430\u0439\u0448\u0435\u0435 \u0432\u0440\u0435\u043c\u044f.\u000a\u000d\u000a\u0420\u0430\u043d\u0435\u0435 \u043f\u043e\u043c\u043e\u0449\u043d\u0438\u043a \u0433\u043b\u0430\u0432\u044b \u0440\u043e\u0441\u0441\u0438\u0439\u0441\u043a\u043e\u0433\u043e \u000d\u000a\u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0430 \u042e\u0440\u0438\u0439 \u0423\u0448\u0430\u043a\u043e\u0432 \u0437\u0430\u044f\u0432\u043b\u044f\u043b, \u0447\u0442\u043e \u000d\u000a\u043f\u0440\u0435\u0434\u0441\u0435\u0434\u0430\u0442\u0435\u043b\u044c \u041a\u041d\u0420 \u0421\u0438 \u0426\u0437\u0438\u043d\u044c\u043f\u0438\u043d \u043f\u0440\u0438\u0433\u043b\u0430\u0441\u0438\u043b \u000d\u000a\u041f\u0443\u0442\u0438\u043d\u0430 \u043d\u0430\u043d\u0435\u0441\u0442\u0438 \u0432\u0438\u0437\u0438\u0442 \u0432 \u041a\u0438\u0442\u0430\u0439 \u0432 \u043f\u0435\u0440\u0432\u043e\u0439 \u000d\u000a\u043f\u043e\u043b\u043e\u0432\u0438\u043d\u0435 \u0433\u043e\u0434\u0430. \u041e\u043d \u0434\u043e\u0431\u0430\u0432\u0438\u043b, \u0447\u0442\u043e \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u000d\u000a\u0431\u044b\u043b\u043e \u043f\u0440\u0438\u043d\u044f\u0442\u043e. \u0423\u0448\u0430\u043a\u043e\u0432 \u043e\u0442\u043c\u0435\u0442\u0438\u043b, \u0447\u0442\u043e \u043b\u0438\u0434\u0435\u0440 \u000d\u000a\u041a\u0438\u0442\u0430\u044f \u0442\u0430\u043a\u0436\u0435 \u043e\u0436\u0438\u0434\u0430\u0435\u0442 \u0441\u0432\u043e\u0435\u0433\u043e \u0440\u043e\u0441\u0441\u0438\u0439\u0441\u043a\u043e\u0433\u043e \u000d\u000a\u043a\u043e\u043b\u043b\u0435\u0433\u0443 \u043d\u0430 \u0441\u0430\u043c\u043c\u0438\u0442\u0435 \u0410\u0422\u042d\u0421 \u0432 \u0428\u0435\u043d\u044c\u0447\u0436\u044d\u043d\u0435 \u000d\u000a\u0432 \u043d\u043e\u044f\u0431\u0440\u0435 \u044d\u0442\u043e\u0433\u043e \u0433\u043e\u0434\u0430.\u000d\u000a07 11","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 20\u201327 \u043c\u0430\u0440\u0442\u0430 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0430\u000d\u000a\u0420\u043e\u0441\u0441\u0438\u0439\u0441\u043a\u043e-\u043a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u0439 \u0444\u043e\u0440\u0443\u043c \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0442\u0435\u043b\u0435\u0439 \u000d\u000a\u043f\u0440\u043e\u0439\u0434\u0435\u0442 \u0432 \u041c\u043e\u0441\u043a\u0432\u0435 \u0432 \u0441\u0435\u043d\u0442\u044f\u0431\u0440\u0435\u000d\u000a\u0412 \u043f\u0440\u043e\u0448\u043b\u044b\u0439 \u0440\u0430\u0437 \u0432 \u043d\u0435\u043c \u043f\u0440\u0438\u043d\u044f\u043b\u0438 \u0443\u0447\u0430\u0441\u0442\u0438\u0435 \u043e\u043a\u043e\u043b\u043e 800 \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u0435\u0439 \u043e\u0431\u0435\u0438\u0445 \u0441\u0442\u0440\u0430\u043d.\u000d\u000a\u0421\u0435\u0434\u044c\u043c\u043e\u0439 \u0420\u043e\u0441\u0441\u0438\u0439\u0441\u043a\u043e-\u043a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u0439 \u0444\u043e\u0440\u0443\u043c \u000d\u000a\u043f\u0440\u0435\u0434\u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0442\u0435\u043b\u0435\u0439 \u043f\u0440\u043e\u0439\u0434\u0435\u0442 \u0432 \u041c\u043e\u0441\u043a\u0432\u0435 \u2028\u000d\u000a10\u201312 \u0441\u0435\u043d\u0442\u044f\u0431\u0440\u044f, \u0437\u0430\u044f\u0432\u0438\u043b \u0441\u043e\u043f\u0440\u0435\u0434\u0441\u0435\u0434\u0430\u0442\u0435\u043b\u044c \u000d\u000a\u0420\u043e\u0441\u0441\u0438\u0439\u0441\u043a\u043e-\u043a\u0438\u0442\u0430\u0439\u0441\u043a\u043e\u0433\u043e \u043a\u043e\u043c\u0438\u0442\u0435\u0442\u0430 \u0434\u0440\u0443\u0436\u0431\u044b, \u043c\u0438\u0440\u0430 \u000d\u000a\u0438 \u0440\u0430\u0437\u0432\u0438\u0442\u0438\u044f, \u0441\u043f\u0435\u0446\u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u044c \u043f\u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442\u0430 \u000d\u000a\u0420\u043e\u0441\u0441\u0438\u0438 \u043f\u043e \u0441\u0432\u044f\u0437\u044f\u043c \u0441 \u043c\u0435\u0436\u0434\u0443\u043d\u0430\u0440\u043e\u0434\u043d\u044b\u043c\u0438 \u000d\u000a\u043e\u0440\u0433\u0430\u043d\u0438\u0437\u0430\u0446\u0438\u044f\u043c\u0438 \u0434\u043b\u044f \u0434\u043e\u0441\u0442\u0438\u0436\u0435\u043d\u0438\u044f \u0446\u0435\u043b\u0435\u0439 \u000d\u000a\u0443\u0441\u0442\u043e\u0439\u0447\u0438\u0432\u043e\u0433\u043e \u0440\u0430\u0437\u0432\u0438\u0442\u0438\u044f \u0411\u043e\u0440\u0438\u0441 \u0422\u0438\u0442\u043e\u0432.\u000a\u000d\u000a\u041e\u043d \u043e\u0442\u043c\u0435\u0442\u0438\u043b, \u0447\u0442\u043e \u043f\u0440\u0435\u0434\u044b\u0434\u0443\u0449\u0438\u0439 \u043f\u043e\u0434\u043e\u0431\u043d\u044b\u0439 \u0444\u043e\u0440\u0443\u043c \u000d\u000a\u0434\u043b\u044f \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u0435\u0439 \u0431\u0438\u0437\u043d\u0435\u0441\u0430 \u0434\u0432\u0443\u0445 \u0441\u0442\u0440\u0430\u043d \u043f\u0440\u043e\u0448\u0435\u043b \u000d\u000a\u0432 \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u043e\u043c \u0421\u0438\u0430\u043d\u0435 \u0432 \u043d\u043e\u044f\u0431\u0440\u0435 \u043f\u0440\u043e\u0448\u043b\u043e\u0433\u043e \u0433\u043e\u0434\u0430. \u000d\u000a\u041d\u0430 \u043d\u0435\u043c \u043f\u0440\u0438\u0441\u0443\u0442\u0441\u0442\u0432\u043e\u0432\u0430\u043b\u0438 \u043e\u043a\u043e\u043b\u043e \u000d\u000a500 \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u0435\u0439 \u041a\u0438\u0442\u0430\u044f \u0438 300 \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u043e\u0432 \u000d\u000a\u043e\u0442 \u0440\u043e\u0441\u0441\u0438\u0439\u0441\u043a\u043e\u0439 \u0441\u0442\u043e\u0440\u043e\u043d\u044b.\u000a\u000d\u000a\u041a\u0440\u043e\u043c\u0435 \u0442\u043e\u0433\u043e, \u0422\u0438\u0442\u043e\u0432 \u0434\u043e\u0431\u0430\u0432\u0438\u043b, \u0447\u0442\u043e \u0421\u043e\u0432\u0435\u0442 \u000d\u000a\u043f\u043e \u043d\u0430\u0443\u043a\u0435 \u0438 \u0438\u043d\u043d\u043e\u0432\u0430\u0446\u0438\u044f\u043c \u0434\u0432\u0443\u0441\u0442\u043e\u0440\u043e\u043d\u043d\u0435\u0433\u043e \u000d\u000a\u043a\u043e\u043c\u0438\u0442\u0435\u0442\u0430 \u0443\u0436\u0435 \u043f\u0440\u043e\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u0435\u0442 \u043f\u0440\u043e\u0432\u0435\u0434\u0435\u043d\u0438\u0435 \u000d\u000a\u0441\u043e\u0432\u043c\u0435\u0441\u0442\u043d\u043e\u0439 \u043a\u043e\u043d\u0444\u0435\u0440\u0435\u043d\u0446\u0438\u0438 \u043f\u043e \u043f\u0440\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u043c\u0443 \u000d\u000a\u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u0438\u044e \u0442\u0435\u0445\u043d\u043e\u043b\u043e\u0433\u0438\u0439 \u0438\u0441\u043a\u0443\u0441\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0433\u043e \u000d\u000a\u0438\u043d\u0442\u0435\u043b\u043b\u0435\u043a\u0442\u0430.\u000d\u000a#\u0444\u0438\u043d\u0430\u043d\u0441\u044b\u000d\u000aZijin Gold \u043d\u0430\u0440\u0430\u0441\u0442\u0438\u0442 \u0441\u0432\u043e\u044e \u0434\u043e\u043b\u044e \u2028\u000d\u000a\u0432 Chifeng Jilong Gold Mining \u0434\u043e 26% \u0437\u0430 $2,64 \u043c\u043b\u0440\u0434\u000d\u000a\u042d\u0442\u043e \u0441\u0434\u0435\u043b\u0430\u0435\u0442 \u0435\u0435 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u043c \u0430\u043a\u0446\u0438\u043e\u043d\u0435\u0440\u043e\u043c \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438.\u000d\u000a\u041a\u0438\u0442\u0430\u0439\u0441\u043a\u0430\u044f Zijin Gold \u043c\u0435\u0436\u0434\u0443\u043d\u0430\u0440\u043e\u0434\u043d\u043e\u0435 \u000d\u000a\u0437\u043e\u043b\u043e\u0442\u043e\u0434\u043e\u0431\u044b\u0432\u0430\u044e\u0449\u0435\u0435 \u043f\u043e\u0434\u0440\u0430\u0437\u0434\u0435\u043b\u0435\u043d\u0438\u0435 Zijin \u000d\u000a\u043f\u043b\u0430\u043d\u0438\u0440\u0443\u0435\u0442 \u043f\u0440\u0438\u043e\u0431\u0440\u0435\u0441\u0442\u0438 \u0434\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u2028\u000d\u000a12,73% \u0430\u043a\u0446\u0438\u0439 \u0434\u0440\u0443\u0433\u043e\u0433\u043e \u043a\u0440\u0443\u043f\u043d\u043e\u0433\u043e \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u043e\u0433\u043e \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044f \u0437\u043e\u043b\u043e\u0442\u0430, Chifeng Jilong Gold \u000d\u000aMining, \u0437\u0430 $2,64 \u043c\u043b\u0440\u0434.\u000a\u000d\u000a\u0421\u043e\u0433\u043b\u0430\u0441\u043d\u043e \u0443\u0441\u043b\u043e\u0432\u0438\u044f\u043c \u0441\u0434\u0435\u043b\u043a\u0438, Zijin Gold \u0432\u044b\u043a\u0443\u043f\u0438\u0442 \u000d\u000a\u0434\u043e\u043b\u0438 \u0443 \u0434\u0432\u0443\u0445 \u0430\u043a\u0446\u0438\u043e\u043d\u0435\u0440\u043e\u0432 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438, \u0430 \u0442\u0430\u043a\u0436\u0435 \u000d\u000a\u043f\u0440\u0438\u043e\u0431\u0440\u0435\u0442\u0435\u0442 \u0434\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0439 \u043e\u0431\u044a\u0435\u043c \u000d\u000a\u0432\u044b\u043f\u0443\u0449\u0435\u043d\u043d\u044b\u0445 \u043d\u0430 \u0413\u043e\u043d\u043a\u043e\u043d\u0433\u0441\u043a\u043e\u0439 \u0444\u043e\u043d\u0434\u043e\u0432\u043e\u0439 \u0431\u0438\u0440\u0436\u0435 \u000d\u000a\u0430\u043a\u0446\u0438\u0439 \u043a\u043b\u0430\u0441\u0441\u0430 H. \u041f\u043e\u0441\u043b\u0435 \u044d\u0442\u043e\u0433\u043e \u0435\u0435 \u0441\u0443\u043c\u043c\u0430\u0440\u043d\u0430\u044f \u000d\u000a\u0434\u043e\u043b\u044f \u0432 Chifeng Jilong Gold Mining \u0441\u043e\u0441\u0442\u0430\u0432\u0438\u0442 \u000d\u000a25,85%. \u042d\u0442\u043e \u0441\u0434\u0435\u043b\u0430\u0435\u0442 Zijin Gold \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u043c \u000d\u000a\u0430\u043a\u0446\u0438\u043e\u043d\u0435\u0440\u043e\u043c \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438.\u000a\u000d\u000aZijin Gold \u0432\u0437\u044f\u043b\u0430 \u043d\u0430 \u0441\u0435\u0431\u044f \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u000d\u000a\u043d\u0435 \u043f\u0440\u043e\u0434\u0430\u0432\u0430\u0442\u044c \u043f\u0440\u0438\u043e\u0431\u0440\u0435\u0442\u0430\u0435\u043c\u044b\u0435 \u0430\u043a\u0446\u0438\u0438 \u000d\u000a\u043d\u0430 \u043f\u0440\u043e\u0442\u044f\u0436\u0435\u043d\u0438\u0438 18 \u043c\u0435\u0441\u044f\u0446\u0435\u0432.\u000a\u000d\u000a\u041f\u043e \u0438\u0442\u043e\u0433\u0430\u043c \u043f\u0440\u043e\u0448\u043b\u043e\u0433\u043e \u0433\u043e\u0434\u0430 Chifeng Jilong Gold \u000d\u000aMining \u043f\u0440\u043e\u0438\u0437\u0432\u0435\u043b\u0430 14,51 \u0442\u043e\u043d\u043d\u044b \u0437\u043e\u043b\u043e\u0442\u0430, \u0447\u0442\u043e \u000d\u000a\u043d\u0430 4,27% \u043c\u0435\u043d\u044c\u0448\u0435 \u043f\u043e\u043a\u0430\u0437\u0430\u0442\u0435\u043b\u044f 2024 \u0433\u043e\u0434\u0430. \u041e\u043d\u0430 \u000d\u000a\u0432\u043b\u0430\u0434\u0435\u0435\u0442 \u0440\u044f\u0434\u043e\u043c \u043f\u0440\u043e\u0435\u043a\u0442\u043e\u0432 \u0432 \u041a\u0438\u0442\u0430\u0435, \u0413\u0430\u043d\u0435 \u000d\u000a\u0438 \u041b\u0430\u043e\u0441\u0435.\u000d\u000a08 11","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 20\u201327 \u043c\u0430\u0440\u0442\u0430 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000aZijin Mining Group \u043f\u043b\u0430\u043d\u0438\u0440\u0443\u0435\u0442 \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u000d\u000a\u0432 \u0434\u043e\u0431\u044b\u0447\u0443 \u0441\u0442\u0440\u0430\u0442\u0435\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u043c\u0435\u0442\u0430\u043b\u043b\u043e\u0432\u000d\u000a\u0421\u0440\u0435\u0434\u0438 \u0435\u0435 \u043f\u0440\u0438\u043e\u0440\u0438\u0442\u0435\u0442\u043e\u0432 \u2014 \u0432\u043e\u043b\u044c\u0444\u0440\u0430\u043c, \u0443\u0440\u0430\u043d \u0438 \u0440\u0435\u0434\u043a\u043e\u0437\u0435\u043c\u0435\u043b\u044c\u043d\u044b\u0435 \u043c\u0435\u0442\u0430\u043b\u043b\u044b.\u000d\u000a\u041a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u0439 \u0433\u043e\u0440\u043d\u043e\u0434\u043e\u0431\u044b\u0432\u0430\u044e\u0449\u0438\u0439 \u0433\u0438\u0433\u0430\u043d\u0442 Zijin \u000d\u000aMining Group \u043f\u043b\u0430\u043d\u0438\u0440\u0443\u0435\u0442 \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u000d\u000a\u0432 \u0441\u0442\u0440\u0430\u0442\u0435\u0433\u0438\u0447\u0435\u0441\u043a\u0438 \u0432\u0430\u0436\u043d\u044b\u0435 \u043c\u0435\u0442\u0430\u043b\u043b\u044b, \u0432 \u0447\u0438\u0441\u043b\u0435 \u000d\u000a\u043a\u043e\u0442\u043e\u0440\u044b\u0445 \u0443\u0440\u0430\u043d \u0438 \u0432\u043e\u043b\u044c\u0444\u0440\u0430\u043c.\u000a\u000d\u000a\u041a\u0430\u043f\u0438\u0442\u0430\u043b\u043e\u0432\u043b\u043e\u0436\u0435\u043d\u0438\u044f \u0431\u0443\u0434\u0443\u0442 \u043e\u0441\u0443\u0449\u0435\u0441\u0442\u0432\u043b\u044f\u0442\u044c\u0441\u044f \u000d\u000a\u0447\u0435\u0440\u0435\u0437 \u0434\u043e\u0447\u0435\u0440\u043d\u0435\u0435 \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u0435 \u043f\u043e \u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044e \u000d\u000a\u0430\u043a\u0442\u0438\u0432\u0430\u043c\u0438 Gold Mountains Asset Management. \u000d\u000a\u0421\u0435\u0439\u0447\u0430\u0441 \u0435\u0433\u043e \u0441\u0443\u043c\u043c\u0430\u0440\u043d\u044b\u0435 \u0430\u043a\u0442\u0438\u0432\u044b \u043f\u0440\u0435\u0432\u044b\u0448\u0430\u044e\u0442 \u000d\u000a$6 \u043c\u043b\u0440\u0434: \u043e\u043a\u043e\u043b\u043e 75% \u0438\u0437 \u043d\u0438\u0445 \u043f\u0440\u0438\u0445\u043e\u0434\u0438\u0442\u0441\u044f \u000d\u000a\u043d\u0430 \u0437\u043e\u043b\u043e\u0442\u043e, \u0430 \u043e\u0441\u0442\u0430\u043b\u044c\u043d\u043e\u0439 \u043e\u0431\u044a\u0435\u043c \u2014 \u043d\u0430 \u043c\u0435\u0434\u044c, \u000d\u000a\u043b\u0438\u0442\u0438\u0439, \u0443\u0440\u0430\u043d \u0438 \u0434\u0440\u0443\u0433\u0438\u0435 \u043c\u0435\u0442\u0430\u043b\u043b\u044b.\u000d\u000a\u041a\u0430\u043a \u0437\u0430\u044f\u0432\u0438\u043b\u0430 \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u044e\u0449\u0438\u0439 \u0434\u0438\u0440\u0435\u043a\u0442\u043e\u0440 Gold \u000d\u000aMountains \u041b\u0438\u0437\u0430 \u041b\u044e, \u0435\u0449\u0435 \u043e\u0434\u043d\u0438\u043c \u043f\u0440\u0438\u043e\u0440\u0438\u0442\u0435\u0442\u043d\u044b\u043c \u000d\u000a\u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435\u043c \u0434\u043b\u044f \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u0441\u0442\u0430\u043d\u0443\u0442 \u000d\u000a\u0440\u0435\u0434\u043a\u043e\u0437\u0435\u043c\u0435\u043b\u044c\u043d\u044b\u0435 \u043c\u0435\u0442\u0430\u043b\u043b\u044b. \u041f\u0440\u0438 \u044d\u0442\u043e\u043c \u043e\u043d\u0430 \u000d\u000a\u0443\u043a\u0430\u0437\u0430\u043b\u0430, \u0447\u0442\u043e \u0440\u0435\u0447\u044c \u043c\u043e\u0436\u0435\u0442 \u0438\u0434\u0442\u0438 \u0442\u043e\u043b\u044c\u043a\u043e \u000d\u000a\u043e \u043f\u0440\u043e\u0435\u043a\u0442\u0430\u0445, \u043d\u0430\u0445\u043e\u0434\u044f\u0449\u0438\u0445\u0441\u044f \u043d\u0430 \u0440\u0430\u043d\u043d\u0435\u0439 \u0441\u0442\u0430\u0434\u0438\u0438 \u000d\u000a\u0440\u0430\u0437\u0440\u0430\u0431\u043e\u0442\u043a\u0438, \u0442\u0430\u043a \u043a\u0430\u043a \u0440\u0435\u0434\u043a\u043e\u0437\u0435\u043c\u0435\u043b\u044c\u043d\u044b\u0435 \u043c\u0435\u0442\u0430\u043b\u043b\u044b \u000d\u000a\u0432 \u043d\u0430\u0441\u0442\u043e\u044f\u0449\u0435\u0435 \u0432\u0440\u0435\u043c\u044f \u0441\u0438\u043b\u044c\u043d\u043e \u043f\u0435\u0440\u0435\u043e\u0446\u0435\u043d\u0435\u043d\u044b.\u000a\u000d\u000a\u041b\u044e \u0434\u043e\u0431\u0430\u0432\u0438\u043b\u0430, \u0447\u0442\u043e \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u043e\u0431\u043b\u0430\u0434\u0430\u0435\u0442 \u000d\u000a\u0431\u043e\u043b\u044c\u0448\u0438\u043c \u0437\u0430\u043f\u0430\u0441\u043e\u043c \u043d\u0430\u043b\u0438\u0447\u043d\u043e\u0441\u0442\u0438 \u0438 \u043c\u043e\u0436\u0435\u0442 \u000d\u000a\u043f\u0440\u0438\u043e\u0431\u0440\u0435\u0442\u0430\u0442\u044c \u0434\u043e\u043b\u0438 \u043a\u0440\u0443\u043f\u043d\u044b\u0445 \u0430\u043a\u0446\u0438\u043e\u043d\u0435\u0440\u043e\u0432 \u0441\u0440\u0430\u0437\u0443.\u000d\u000a#\u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0430 #\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b\u000d\u000a\u041a\u0438\u0442\u0430\u0439 \u0441\u043e\u0441\u0442\u0430\u0432\u043b\u044f\u0435\u0442 \u043a\u0430\u0440\u0442\u044b \u043e\u043a\u0435\u0430\u043d\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u0434\u043d\u0430 \u000d\u000a\u043d\u0430 \u0441\u043b\u0443\u0447\u0430\u0439 \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u0430 \u0441 \u0421\u0428\u0410\u000d\u000a\u0420\u0435\u0447\u044c \u0438\u0434\u0435\u0442 \u043e\u0431 \u0430\u043a\u0432\u0430\u0442\u043e\u0440\u0438\u044f\u0445 \u0422\u0438\u0445\u043e\u0433\u043e, \u0418\u043d\u0434\u0438\u0439\u0441\u043a\u043e\u0433\u043e \u0438 \u0421\u0435\u0432\u0435\u0440\u043d\u043e\u0433\u043e \u041b\u0435\u0434\u043e\u0432\u0438\u0442\u043e\u0433\u043e \u043e\u043a\u0435\u0430\u043d\u043e\u0432.\u000d\u000a\u041a\u041d\u0420 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442 \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0434\u0435\u0441\u044f\u0442\u043a\u043e\u0432 \u000d\u000a\u0438\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u044c\u0441\u043a\u0438\u0445 \u0441\u0443\u0434\u043e\u0432 \u0434\u043b\u044f \u0441\u043e\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u0438\u044f \u000d\u000a\u043f\u043e\u0434\u0440\u043e\u0431\u043d\u043e\u0439 \u043a\u0430\u0440\u0442\u044b \u043e\u043a\u0435\u0430\u043d\u0441\u043a\u043e\u0433\u043e \u0434\u043d\u0430 \u043d\u0430 \u0441\u043b\u0443\u0447\u0430\u0439 \u000d\u000a\u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e\u0433\u043e \u0432\u043e\u0435\u043d\u043d\u043e\u0433\u043e \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u0430 \u0441 \u0421\u0428\u0410, \u000d\u000a\u0441\u043e\u043e\u0431\u0449\u0430\u0435\u0442 \u0430\u0433\u0435\u043d\u0442\u0441\u0442\u0432\u043e Reuters.\u000a\u000d\u000a\u041e\u043f\u0440\u043e\u0448\u0435\u043d\u043d\u044b\u0435 \u0438\u043c \u044d\u043a\u0441\u043f\u0435\u0440\u0442\u044b \u0443\u043a\u0430\u0437\u0430\u043b\u0438, \u0447\u0442\u043e \u044d\u0442\u043e \u000d\u000a\u043c\u043e\u0436\u0435\u0442 \u0434\u0430\u0442\u044c \u041f\u0435\u043a\u0438\u043d\u0443 \u043f\u0440\u0435\u0438\u043c\u0443\u0449\u0435\u0441\u0442\u0432\u043e \u0432 \u0441\u043b\u0443\u0447\u0430\u0435 \u000d\u000a\u0431\u043e\u0435\u0432\u044b\u0445 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0439 \u043c\u0435\u0436\u0434\u0443 \u0441\u0443\u0431\u043c\u0430\u0440\u0438\u043d\u0430\u043c\u0438 \u0438\u043b\u0438 \u043f\u0440\u0438 \u000d\u000a\u043e\u0440\u0433\u0430\u043d\u0438\u0437\u0430\u0446\u0438\u0438 \u0434\u0438\u0432\u0435\u0440\u0441\u0438\u043e\u043d\u043d\u044b\u0445 \u043e\u043f\u0435\u0440\u0430\u0446\u0438\u0439 \u043f\u0440\u043e\u0442\u0438\u0432 \u000d\u000a\u043c\u043e\u0440\u0441\u043a\u043e\u0439 \u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u044b \u0421\u0428\u0410 \u0438 \u0438\u0445 \u000d\u000a\u0441\u043e\u044e\u0437\u043d\u0438\u043a\u043e\u0432. \u0422\u0430\u043a\u0438\u0435 \u0438\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u043d\u0438\u044f \u0442\u0430\u043a\u0436\u0435 \u043c\u043e\u0433\u0443\u0442 \u000d\u000a\u0431\u044b\u0442\u044c \u0441\u0432\u044f\u0437\u0430\u043d\u044b \u0441 \u043f\u043e\u0438\u0441\u043a\u043e\u043c \u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u0439 \u000d\u000a\u043f\u043e\u043b\u0435\u0437\u043d\u044b\u0445 \u0438\u0441\u043a\u043e\u043f\u0430\u0435\u043c\u044b\u0445.\u000d\u000a\u0412 \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u0435 \u043f\u0440\u0438\u043c\u0435\u0440\u0430 \u0430\u0433\u0435\u043d\u0442\u0441\u0442\u0432\u043e \u043f\u0440\u0438\u0432\u043e\u0434\u0438\u0442 \u000d\u000a\u043c\u0430\u0440\u0448\u0440\u0443\u0442 \u0438\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u044c\u0441\u043a\u043e\u0433\u043e \u043a\u043e\u0440\u0430\u0431\u043b\u044f \u000d\u000a\u00ab\u0414\u0443\u043d\u0444\u0430\u043d\u0445\u0443\u043d-3\u00bb: \u0432 2024 \u0438 2025 \u0433\u043e\u0434\u0430\u0445 \u043e\u043d \u000d\u000a\u0441\u043e\u0441\u0442\u0430\u0432\u043b\u044f\u043b \u043a\u0430\u0440\u0442\u044b \u043c\u043e\u0440\u0441\u043a\u043e\u0433\u043e \u0434\u043d\u0430 \u0432 \u0430\u043a\u0432\u0430\u0442\u043e\u0440\u0438\u044f\u0445 \u000d\u000a\u042e\u0436\u043d\u043e \u041a\u0438\u0442\u0430\u0439\u0441\u043a\u043e\u0433\u043e \u043c\u043e\u0440\u044f, \u0430 \u0442\u0430\u043a\u0436\u0435 \u0432\u043e\u0437\u043b\u0435 \u000d\u000a\u0422\u0430\u0439\u0432\u0430\u043d\u044f, \u0428\u0440\u0438 \u041b\u0430\u043d\u043a\u0438, \u041c\u0430\u043b\u0430\u043a\u043a\u0441\u043a\u043e\u0433\u043e \u043f\u0440\u043e\u043b\u0438\u0432\u0430 \u000d\u000a\u0438 \u043e\u0441\u0442\u0440\u043e\u0432\u0430 \u0413\u0443\u0430\u043c, \u0433\u0434\u0435 \u0440\u0430\u0441\u043f\u043e\u043b\u043e\u0436\u0435\u043d\u0430 \u043a\u0440\u0443\u043f\u043d\u0430\u044f \u000d\u000a\u0432\u043e\u0435\u043d\u043d\u0430\u044f \u0431\u0430\u0437\u0430 \u0421\u0428\u0410. \u0412 \u043e\u0431\u0449\u0435\u0439 \u0441\u043b\u043e\u0436\u043d\u043e\u0441\u0442\u0438 \u000d\u000aReuters \u043f\u0440\u043e\u0430\u043d\u0430\u043b\u0438\u0437\u0438\u0440\u043e\u0432\u0430\u043b \u043c\u0430\u0440\u0448\u0440\u0443\u0442\u044b \u000d\u000a42 \u043f\u043e\u0434\u043e\u0431\u043d\u044b\u0445 \u0441\u0443\u0434\u043e\u0432: \u043e\u043d\u0438 \u043a\u0443\u0440\u0441\u0438\u0440\u043e\u0432\u0430\u043b\u0438 \u0432\u043e\u0437\u043b\u0435 \u000d\u000a\u043f\u043e\u0431\u0435\u0440\u0435\u0436\u044c\u044f \u042f\u043f\u043e\u043d\u0438\u0438, \u0424\u0438\u043b\u0438\u043f\u043f\u0438\u043d, \u0418\u043d\u0434\u0438\u0438, \u000d\u000a\u0411\u0430\u043d\u0433\u043b\u0430\u0434\u0435\u0448 \u0438 \u041f\u0430\u043a\u0438\u0441\u0442\u0430\u043d\u0430, \u0430 \u0442\u0430\u043a\u0436\u0435 \u0432 \u0437\u0430\u043f\u0430\u0434\u043d\u044b\u0445 \u000d\u000a\u0440\u0430\u0439\u043e\u043d\u0430\u0445 \u0422\u0438\u0445\u043e\u0433\u043e \u043e\u043a\u0435\u0430\u043d\u0430.\u000d\u000a09 11","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 20\u201327 \u043c\u0430\u0440\u0442\u0430 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u041a\u0438\u0442\u0430\u0439 \u0441 2023 \u0433\u043e\u0434\u0430 \u0432\u043b\u043e\u0436\u0438\u043b $120 \u043c\u043b\u0440\u0434 \u0432 \u0434\u043e\u0431\u044b\u0447\u0443 \u000d\u000a\u0438 \u043f\u0435\u0440\u0435\u0440\u0430\u0431\u043e\u0442\u043a\u0443 \u043d\u0438\u043a\u0435\u043b\u044f \u0438 \u0434\u0440\u0443\u0433\u0438\u0445 \u043c\u0438\u043d\u0435\u0440\u0430\u043b\u043e\u0432 \u0437\u0430 \u0440\u0443\u0431\u0435\u0436\u043e\u043c\u000d\u000a\u041a\u0440\u043e\u043c\u0435 \u0442\u043e\u0433\u043e, \u0441\u0442\u0440\u0430\u043d\u0430 \u043f\u0440\u0438\u043e\u0431\u0440\u0435\u043b\u0430 \u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u044f \u043b\u0438\u0442\u0438\u044f, \u043c\u0435\u0434\u0438 \u0438 \u0440\u0435\u0434\u043a\u043e\u0437\u0435\u043c\u0435\u043b\u044c\u043d\u044b\u0445 \u043c\u0435\u0442\u0430\u043b\u043b\u043e\u0432.\u000d\u000a\u041a\u041d\u0420 \u0441 2023 \u0433\u043e\u0434\u0430 \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0440\u043e\u0432\u0430\u043b\u0430 \u0432 \u0434\u043e\u0431\u044b\u0447\u0443 \u000d\u000a\u0438 \u043f\u0435\u0440\u0435\u0440\u0430\u0431\u043e\u0442\u043a\u0443 \u043d\u0438\u043a\u0435\u043b\u044f \u0438 \u0434\u0440\u0443\u0433\u0438\u0445 \u043a\u0440\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u000d\u000a\u0432\u0430\u0436\u043d\u044b\u0445 \u043c\u0438\u043d\u0435\u0440\u0430\u043b\u043e\u0432 \u0431\u043e\u043b\u0435\u0435 $120 \u043c\u043b\u0440\u0434, \u0433\u043e\u0432\u043e\u0440\u0438\u0442\u0441\u044f \u000d\u000a\u0432 \u0434\u043e\u043a\u043b\u0430\u0434\u0435 \u0430\u0432\u0441\u0442\u0440\u0430\u043b\u0438\u0439\u0441\u043a\u043e\u0433\u043e \u0430\u043d\u0430\u043b\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u000d\u000a\u0446\u0435\u043d\u0442\u0440\u0430 Climate Energy Finance (CEF).\u000a\u000d\u000a\u041f\u043e \u0435\u0433\u043e \u0434\u0430\u043d\u043d\u044b\u043c, \u041a\u0438\u0442\u0430\u0439 \u0442\u0430\u043a\u0436\u0435 \u0432\u043b\u043e\u0436\u0438\u043b \u0441\u0440\u0435\u0434\u0441\u0442\u0432\u0430 \u000d\u000a\u0432 \u043f\u0440\u043e\u0435\u043a\u0442\u044b \u043f\u043e \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0443 \u043b\u0438\u0442\u0438\u044f, \u043c\u0435\u0434\u0438, \u000d\u000a\u0440\u0435\u0434\u043a\u043e\u0437\u0435\u043c\u0435\u043b\u044c\u043d\u044b\u0445 \u043c\u0435\u0442\u0430\u043b\u043b\u043e\u0432 \u0438 \u0431\u043e\u043a\u0441\u0438\u0442\u043e\u0432. \u041a\u0430\u043a \u000d\u000a\u0443\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u0432 \u0434\u043e\u043a\u043b\u0430\u0434\u0435, \u041f\u0435\u043a\u0438\u043d \u0441\u0442\u0440\u0435\u043c\u0438\u0442\u0441\u044f \u000d\u000a\u043a \u0434\u043e\u043c\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044e \u043d\u0435 \u0442\u043e\u043b\u044c\u043a\u043e \u0432 \u0441\u0444\u0435\u0440\u0435 \u0434\u043e\u0431\u044b\u0447\u0438 \u000d\u000a\u0440\u0435\u0441\u0443\u0440\u0441\u043e\u0432, \u043d\u043e \u0438 \u0432\u043e \u0432\u0441\u0435\u0439 \u0446\u0435\u043f\u043e\u0447\u043a\u0435 \u0441\u043e\u0437\u0434\u0430\u043d\u0438\u044f \u043d\u0430 \u0438\u0445 \u000d\u000a\u043e\u0441\u043d\u043e\u0432\u0435 \u0442\u043e\u0432\u0430\u0440\u043e\u0432 \u0441 \u0432\u044b\u0441\u043e\u043a\u043e\u0439 \u0434\u043e\u0431\u0430\u0432\u043b\u0435\u043d\u043d\u043e\u0439 \u000d\u000a\u0441\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u044c\u044e.\u000a\u000d\u000a\u041f\u043e \u043e\u0446\u0435\u043d\u043a\u0435 CEF, \u041a\u0438\u0442\u0430\u0439 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u0438\u0440\u0443\u0435\u0442 \u000d\u000a90% \u043c\u0438\u0440\u043e\u0432\u043e\u0433\u043e \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u0440\u0435\u0434\u043a\u043e\u0437\u0435\u043c\u0435\u043b\u044c\u043d\u044b\u0445 \u000d\u000a\u043c\u0435\u0442\u0430\u043b\u043b\u043e\u0432, 60% \u043f\u0435\u0440\u0435\u0440\u0430\u0431\u043e\u0442\u043a\u0438 \u043b\u0438\u0442\u0438\u044f, \u0431\u043e\u043b\u0435\u0435 \u000d\u000a70% \u2014 \u043a\u043e\u0431\u0430\u043b\u044c\u0442\u0430 \u0438 \u0441\u0432\u044b\u0448\u0435 \u043f\u043e\u043b\u043e\u0432\u0438\u043d\u044b \u043c\u0438\u0440\u043e\u0432\u043e\u0433\u043e \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u0441\u0442\u0430\u043b\u0438. \u041a\u0440\u043e\u043c\u0435 \u0442\u043e\u0433\u043e, \u0432 \u041a\u041d\u0420 \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0441\u044f \u0431\u043e\u043b\u0435\u0435 90% \u043c\u0430\u0442\u0435\u0440\u0438\u0430\u043b\u043e\u0432 \u0434\u043b\u044f \u000d\u000a\u0430\u043a\u043a\u0443\u043c\u0443\u043b\u044f\u0442\u043e\u0440\u043d\u044b\u0445 \u043a\u0430\u0442\u043e\u0434\u043e\u0432 \u0438 \u0430\u043d\u043e\u0434\u043e\u0432.\u000a\u000d\u000a\u0417\u043d\u0430\u0447\u0438\u0442\u0435\u043b\u044c\u043d\u0430\u044f \u0447\u0430\u0441\u0442\u044c \u043a\u0430\u043f\u0438\u0442\u0430\u043b\u043e\u0432\u043b\u043e\u0436\u0435\u043d\u0438\u0439 \u041a\u0438\u0442\u0430\u044f \u000d\u000a\u0432 \u0437\u0430\u0440\u0443\u0431\u0435\u0436\u043d\u0443\u044e \u0433\u043e\u0440\u043d\u043e\u0434\u043e\u0431\u044b\u0447\u0443 \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u000d\u000a\u0432 \u0441\u0442\u0440\u0430\u043d\u044b \u0410\u0444\u0440\u0438\u043a\u0438, \u041b\u0430\u0442\u0438\u043d\u0441\u043a\u043e\u0439 \u0410\u043c\u0435\u0440\u0438\u043a\u0438 \u2028\u000d\u000a\u0438 \u042e\u0433\u043e-\u0412\u043e\u0441\u0442\u043e\u0447\u043d\u043e\u0439 \u0410\u0437\u0438\u0438.\u000a\u000d\u000a\u041a\u0440\u043e\u043c\u0435 \u0442\u043e\u0433\u043e, \u0441\u0442\u0440\u0430\u0442\u0435\u0433\u0438\u044f \u041f\u0435\u043a\u0438\u043d\u0430 \u0432 \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0438\u0435 \u000d\u000a\u0433\u043e\u0434\u044b \u044d\u0432\u043e\u043b\u044e\u0446\u0438\u043e\u043d\u0438\u0440\u043e\u0432\u0430\u043b\u0430 \u0432 \u0431\u043e\u043b\u0435\u0435 \u0433\u043b\u0443\u0431\u043e\u043a\u043e\u0435 \u000d\u000a\u043f\u0430\u0440\u0442\u043d\u0435\u0440\u0441\u0442\u0432\u043e \u0441 \u0432\u043b\u0430\u0441\u0442\u044f\u043c\u0438 \u0438\u043d\u043e\u0441\u0442\u0440\u0430\u043d\u043d\u044b\u0445 \u000d\u000a\u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432. \u0422\u0435\u043f\u0435\u0440\u044c \u041a\u041d\u0420 \u043d\u0435 \u0442\u043e\u043b\u044c\u043a\u043e \u000d\u000a\u043f\u0440\u0438\u043e\u0431\u0440\u0435\u0442\u0430\u0435\u0442 \u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u044f, \u043d\u043e \u0438 \u0441\u043e\u0437\u0434\u0430\u0435\u0442 \u000d\u000a\u0432 \u044d\u0442\u0438\u0445 \u0441\u0442\u0440\u0430\u043d\u0430\u0445 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u043f\u043e \u043f\u0435\u0440\u0435\u0440\u0430\u0431\u043e\u0442\u043a\u0435 \u000d\u000a\u0434\u043e\u0431\u044b\u0442\u043e\u0433\u043e \u0441\u044b\u0440\u044c\u044f, \u0430 \u0442\u0430\u043a\u0436\u0435 \u0441\u0442\u0440\u043e\u0438\u0442 \u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u0443\u044e \u000d\u000a\u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0443 \u2014 \u0436\u0435\u043b\u0435\u0437\u043d\u044b\u0435 \u0434\u043e\u0440\u043e\u0433\u0438, \u043f\u043e\u0440\u0442\u044b \u000d\u000a\u0438 \u043e\u0431\u044a\u0435\u043a\u0442\u044b \u044d\u043d\u0435\u0440\u0433\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u043f\u0440\u043e\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u043e\u0441\u0442\u0438. \u000d\u000a\u0412\u0437\u0430\u043c\u0435\u043d \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u0430\u044f \u0441\u0442\u043e\u0440\u043e\u043d\u0430 \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u0431\u043e\u043b\u0435\u0435 \u000d\u000a\u0434\u043e\u043b\u0433\u043e\u0441\u0440\u043e\u0447\u043d\u044b\u0435 \u043a\u043e\u043d\u0442\u0440\u0430\u043a\u0442\u044b \u043d\u0430 \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0438 \u0441\u044b\u0440\u044c\u044f \u000d\u000a\u0438 \u043f\u0440\u043e\u0434\u0443\u043a\u0442\u043e\u0432 \u0435\u0433\u043e \u043f\u0435\u0440\u0435\u0440\u0430\u0431\u043e\u0442\u043a\u0438.\u000d\u000a10 11","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 20\u201327 \u043c\u0430\u0440\u0442\u0430 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u041a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u0435 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u0438 \u0437\u043e\u043b\u043e\u0442\u0430 \u0432 2026 \u0433\u043e\u0434\u0443 \u000d\u000a\u043e\u043f\u0435\u0440\u0435\u0434\u044f\u0442 \u0437\u0430\u0440\u0443\u0431\u0435\u0436\u043d\u044b\u0445 \u043a\u043e\u043d\u043a\u0443\u0440\u0435\u043d\u0442\u043e\u0432 \u043f\u043e \u043f\u0440\u0438\u0431\u044b\u043b\u0438\u000d\u000a\u041e\u043d\u0438 \u043d\u0435 \u0431\u043e\u044f\u0442\u0441\u044f \u0440\u0438\u0441\u043a\u043e\u0432\u0430\u043d\u043d\u044b\u0445 \u0430\u043a\u0442\u0438\u0432\u043e\u0432 \u0438 \u043c\u043e\u0433\u0443\u0442 \u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0432 \u0442\u0435\u043a\u0443\u0449\u0435\u043c \u0433\u043e\u0434\u0443 \u0440\u0435\u043a\u043e\u0440\u0434\u043d\u044b\u0435 \u000d\u000a\u0434\u043e\u0445\u043e\u0434\u044b.\u000d\u000a\u0412\u0435\u0434\u0443\u0449\u0438\u0435 \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u0435 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u0438 \u0437\u043e\u043b\u043e\u0442\u0430 \u000d\u000a\u043f\u043e \u0438\u0442\u043e\u0433\u0430\u043c 2026 \u0433\u043e\u0434\u0430 \u043c\u043e\u0433\u0443\u0442 \u043f\u043e\u043a\u0430\u0437\u0430\u0442\u044c \u043b\u0443\u0447\u0448\u0438\u0435 \u000d\u000a\u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u044b \u0438 \u043f\u043e\u043b\u0443\u0447\u0438\u0442\u044c \u0431\u043e\u043b\u044c\u0448\u0443\u044e \u043f\u0440\u0438\u0431\u044b\u043b\u044c, \u0447\u0435\u043c \u0438\u0445 \u000d\u000a\u043a\u043e\u043d\u043a\u0443\u0440\u0435\u043d\u0442\u044b \u0437\u0430 \u0440\u0443\u0431\u0435\u0436\u043e\u043c, \u043f\u0438\u0448\u0435\u0442 Bloomberg. \u041a\u0430\u043a \u000d\u000a\u043e\u0442\u043c\u0435\u0447\u0430\u0435\u0442 \u0430\u0433\u0435\u043d\u0442\u0441\u0442\u0432\u043e, \u044d\u0442\u043e \u043f\u0440\u043e\u0438\u0437\u043e\u0439\u0434\u0435\u0442 \u0438\u0437-\u0437\u0430 \u000d\u000a\u0432\u044b\u0441\u043e\u043a\u0438\u0445 \u0446\u0435\u043d \u043d\u0430 \u0434\u0440\u0430\u0433\u043e\u0446\u0435\u043d\u043d\u044b\u0439 \u043c\u0435\u0442\u0430\u043b\u043b \u0438 \u043e\u0441\u043e\u0431\u0435\u043d\u043d\u043e \u000d\u000a\u0430\u043c\u0431\u0438\u0446\u0438\u043e\u0437\u043d\u044b\u0445 \u043f\u043b\u0430\u043d\u043e\u0432 \u041a\u041d\u0420 \u043f\u043e \u0440\u0430\u0437\u0432\u0438\u0442\u0438\u044e \u0431\u0438\u0437\u043d\u0435\u0441\u0430.\u000a\u000d\u000a\u041f\u043e \u043f\u0440\u043e\u0433\u043d\u043e\u0437\u0443 Bloomberg, Zijin Gold International, \u000d\u000aShandong Gold Mining, \u0430 \u0442\u0430\u043a\u0436\u0435 Chifeng Jilong \u000d\u000aGold Mining \u043f\u043e \u0438\u0442\u043e\u0433\u0430\u043c \u0442\u0435\u043a\u0443\u0449\u0435\u0433\u043e \u0433\u043e\u0434\u0430 \u043c\u043e\u0433\u0443\u0442 \u000d\u000a\u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0440\u0435\u043a\u043e\u0440\u0434\u043d\u0443\u044e \u043f\u0440\u0438\u0431\u044b\u043b\u044c. \u0410\u0433\u0435\u043d\u0442\u0441\u0442\u0432\u043e \u000d\u000a\u0443\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442, \u0447\u0442\u043e \u0437\u0430\u0440\u0443\u0431\u0435\u0436\u043d\u044b\u0435 \u043a\u043e\u043d\u043a\u0443\u0440\u0435\u043d\u0442\u044b \u2028\u000d\u000a\u0432 2026 \u0433\u043e\u0434\u0443, \u0432\u0435\u0440\u043e\u044f\u0442\u043d\u043e, \u0441\u043e\u043a\u0440\u0430\u0442\u044f\u0442 \u043e\u0431\u044a\u0435\u043c\u044b \u0434\u043e\u0431\u044b\u0447\u0438 \u000d\u000a\u0438 \u043d\u0435 \u0441\u043c\u043e\u0433\u0443\u0442 \u0440\u0430\u0441\u0448\u0438\u0440\u0438\u0442\u044c \u043f\u043e\u0440\u0442\u0444\u0435\u043b\u044c \u043f\u0440\u043e\u0435\u043a\u0442\u043e\u0432, \u2028\u000d\u000a\u0432 \u0442\u043e \u0436\u0435 \u0432\u0440\u0435\u043c\u044f \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u0435 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u043f\u043b\u0430\u043d\u0438\u0440\u0443\u044e\u0442 \u000d\u000a\u043d\u0430\u0440\u0430\u0441\u0442\u0438\u0442\u044c \u043e\u0431\u044a\u0435\u043c\u044b \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u0438 \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0430\u044e\u0442 \u000d\u000a\u0430\u043a\u0442\u0438\u0432\u043d\u043e \u043f\u0440\u0438\u043e\u0431\u0440\u0435\u0442\u0430\u0442\u044c \u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u044f \u0437\u043e\u043b\u043e\u0442\u0430 \u2028\u000d\u000a\u0437\u0430 \u0440\u0443\u0431\u0435\u0436\u043e\u043c.\u000d\u000aZijin Gold International \u0432 2025 \u0433\u043e\u0434\u0443 \u0434\u043e\u0431\u044b\u043b\u0430 \u000d\u000a46,9 \u0442\u043e\u043d\u043d\u044b \u0437\u043e\u043b\u043e\u0442\u0430, \u0447\u0442\u043e \u043d\u0430 20% \u0431\u043e\u043b\u044c\u0448\u0435 \u000d\u000a\u043f\u043e\u043a\u0430\u0437\u0430\u0442\u0435\u043b\u044f 2024 \u0433\u043e\u0434\u0430. \u041f\u0440\u0438 \u044d\u0442\u043e\u043c \u043f\u0440\u0438\u0431\u044b\u043b\u044c \u000d\u000a\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u0432\u044b\u0440\u043e\u0441\u043b\u0430 \u0432 \u0442\u0440\u0438 \u0440\u0430\u0437\u0430, \u043d\u0430 202%, \u000d\u000a\u0434\u043e $1,87 \u043c\u043b\u0440\u0434. \u041a\u0440\u043e\u043c\u0435 \u0442\u043e\u0433\u043e, \u043e\u043d\u0430 \u043e\u0442\u0447\u0438\u0442\u0430\u043b\u0430\u0441\u044c \u000d\u000a\u043e \u043d\u0430\u043b\u0438\u0447\u0438\u0438 $3,62 \u043c\u043b\u0440\u0434 \u0434\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0432, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u000d\u000a\u0441\u043c\u043e\u0436\u0435\u0442 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u044c \u0434\u043b\u044f \u043f\u043e\u043a\u0443\u043f\u043a\u0438 \u043d\u043e\u0432\u044b\u0445 \u000d\u000a\u0440\u0443\u0434\u043d\u0438\u043a\u043e\u0432 \u0438\u043b\u0438 \u0434\u043e\u043b\u0435\u0439 \u0434\u0440\u0443\u0433\u0438\u0445 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0439. \u000d\u000a\u0412 2026 \u0433\u043e\u0434\u0443 Zijin Gold \u043f\u043b\u0430\u043d\u0438\u0440\u0443\u0435\u0442 \u0434\u043e\u0431\u044b\u0442\u044c \u000d\u000a59,2 \u0442\u043e\u043d\u043d\u044b \u0437\u043e\u043b\u043e\u0442\u0430.\u000a\u000d\u000a\u041f\u043e\u043c\u0438\u043c\u043e \u044d\u0442\u043e\u0433\u043e, \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u0435 \u0433\u043e\u0440\u043d\u043e\u0434\u043e\u0431\u044b\u0432\u0430\u044e\u0449\u0438\u0435 \u000d\u000a\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u043f\u0440\u0438 \u0434\u0438\u043f\u043b\u043e\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0435 \u000d\u000a\u0432\u043b\u0430\u0441\u0442\u0435\u0439 \u041a\u041d\u0420 \u0441\u043a\u0443\u043f\u0430\u044e\u0442 \u0440\u0443\u0434\u043d\u0438\u043a\u0438 \u0432 \u0442\u0435\u0445 \u0441\u0442\u0440\u0430\u043d\u0430\u0445 \u000d\u000a\u0438 \u0440\u0435\u0433\u0438\u043e\u043d\u0430\u0445 \u043c\u0438\u0440\u0430, \u043a\u043e\u0442\u043e\u0440\u044b\u0445 \u0434\u0440\u0443\u0433\u0438\u0435 \u043c\u0438\u0440\u043e\u0432\u044b\u0435 \u000d\u000a\u0437\u043e\u043b\u043e\u0442\u043e\u0434\u043e\u0431\u044b\u0432\u0430\u044e\u0449\u0438\u0435 \u0433\u0438\u0433\u0430\u043d\u0442\u044b \u043f\u044b\u0442\u0430\u044e\u0442\u0441\u044f \u000d\u000a\u0438\u0437\u0431\u0435\u0433\u0430\u0442\u044c.\u000d\u000a11 11"]